parameterValue = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'parameterValue'), AbstractGeneralParameterValuePropertyType, documentation='gml:parameterValue is a composition association to a parameter value or group of parameter values used by a coordinate operation.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/coordinateOperations.xsd', 243, 1))
_Namespace_gml.addCategoryObject('elementBinding', parameterValue.name().localName(), parameterValue)

AbstractGeneralParameterValue = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'AbstractGeneralParameterValue'), AbstractGeneralParameterValueType, abstract=pyxb.binding.datatypes.boolean(1), documentation='gml:AbstractGeneralParameterValue is an abstract parameter value or group of parameter values.\nThis abstract complexType is expected to be extended and restricted for well-known operation methods with many instances, in Application Schemas that define operation-method-specialized element names and contents. Specific parameter value elements are directly contained in concrete subtypes, not in this abstract type. All concrete types derived from this type shall extend this type to include one "...Value" element with an appropriate type, which should be one of the element types allowed in the ParameterValueType. In addition, all derived concrete types shall extend this type to include a "operationParameter" property element that references one element substitutable for the "OperationParameter" object element.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/coordinateOperations.xsd', 283, 1))
_Namespace_gml.addCategoryObject('elementBinding', AbstractGeneralParameterValue.name().localName(), AbstractGeneralParameterValue)

integerValueList = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'integerValueList'), integerList, documentation='gml:integerValueList is an ordered sequence of two or more integer values of an operation parameter list, usually used for counts. These integer values do not have an associated unit of measure. An element of this type contains a space-separated sequence of integer values.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/coordinateOperations.xsd', 349, 1))
_Namespace_gml.addCategoryObject('elementBinding', integerValueList.name().localName(), integerValueList)

formula = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'formula'), CodeType, documentation='gml:formula Formula(s) or procedure used by an operation method. The use of the codespace attribite has been deprecated. The property value shall be a character string.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/coordinateOperations.xsd', 417, 1))
_Namespace_gml.addCategoryObject('elementBinding', formula.name().localName(), formula)

axisAbbrev = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'axisAbbrev'), CodeType, documentation='gml:axisAbbrev is the abbreviation used for this coordinate system axis; this abbreviation is also used to identify the coordinates in the coordinate tuple. The codeSpace attribute may reference a source of more information on a set of standardized abbreviations, or on this abbreviation.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/coordinateSystems.xsd', 42, 1))
_Namespace_gml.addCategoryObject('elementBinding', axisAbbrev.name().localName(), axisAbbrev)

rangeSet = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'rangeSet'), RangeSetType, documentation='The gml:rangeSet property element contains the values of the coverage (sometimes called the attribute values).  Its content model is given by gml:RangeSetType.\nThis content model supports a structural description of the range.  The semantic information describing the range set is embedded using a uniform method, as part of the explicit values, or as a template value accompanying the representation using gml:DataBlock and gml:File.\nThe values from each component (or "band") in the range may be encoded within a gml:ValueArray element or a concrete member of the gml:AbstractScalarValueList substitution group . Use of these elements satisfies the value-type homogeneity requirement.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/coverage.xsd', 88, 1))
_Namespace_gml.addCategoryObject('elementBinding', rangeSet.name().localName(), rangeSet)

DataBlock = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'DataBlock'), DataBlockType, documentation='gml:DataBlock describes the Range as a block of text encoded values similar to a Common Separated Value (CSV) representation.\nThe range set parameterization is described by the property gml:rangeParameters.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/coverage.xsd', 103, 1))
_Namespace_gml.addCategoryObject('elementBinding', DataBlock.name().localName(), DataBlock)

tupleList = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'tupleList'), CoordinatesType, documentation='gml:CoordinatesType consists of a list of coordinate tuples, with each coordinate tuple separated by the ts or tuple separator (whitespace), and each coordinate in the tuple by the cs or coordinate separator (comma).\nThe gml:tupleList encoding is effectively "band-interleaved".', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/coverage.xsd', 119, 1))
_Namespace_gml.addCategoryObject('elementBinding', tupleList.name().localName(), tupleList)

File = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'File'), FileType, documentation='for efficiency reasons, GML also provides a means of encoding the range set in an arbitrary external encoding, such as a binary file.  This encoding may be "well-known" but this is not required. This mode uses the gml:File element.\nThe values of the coverage (attribute values in the range set) are transmitted in a external file that is referenced from the XML structure described by gml:FileType.  The external file is referenced by the gml:fileReference property that is an anyURI (the gml:fileName property has been deprecated).  This means that the external file may be located remotely from the referencing GML instance. \nThe gml:compression property points to a definition of a compression algorithm through an anyURI.  This may be a retrievable, computable definition or simply a reference to an unambiguous name for the compression method.\nThe gml:mimeType property points to a definition of the file mime type.\nThe gml:fileStructure property is defined by a codelist. Note further that all values shall be enclosed in a single file. Multi-file structures for values are not supported in GML.\nThe semantics of the range set is described as above using the gml:rangeParameters property.\nNote that if any compression algorithm is applied, the structure above applies only to the pre-compression or post-decompression structure of the file.\nNote that the fields within a record match the gml:valueComponents of the gml:CompositeValue in document order.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/coverage.xsd', 130, 1))
_Namespace_gml.addCategoryObject('elementBinding', File.name().localName(), File)

coverageFunction = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'coverageFunction'), CoverageFunctionType, documentation='The gml:coverageFunction property describes the mapping function from the domain to the range of the coverage.\nThe value of the CoverageFunction is one of gml:CoverageMappingRule and gml:GridFunction.\nIf the gml:coverageFunction property is omitted for a gridded coverage (including rectified gridded coverages) the gml:startPoint is assumed to be the value of the gml:low property in the gml:Grid geometry, and the gml:sequenceRule is assumed to be linear and the gml:axisOrder property is assumed to be "+1 +2".', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/coverage.xsd', 158, 1))
_Namespace_gml.addCategoryObject('elementBinding', coverageFunction.name().localName(), coverageFunction)

CoverageMappingRule = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'CoverageMappingRule'), MappingRuleType, documentation="gml:CoverageMappingRule provides a formal or informal description of the coverage function.\nThe mapping rule may be defined as an in-line string (gml:ruleDefinition) or via a remote reference through xlink:href (gml:ruleReference).  \nIf no rule name is specified, the default is 'Linear' with respect to members of the domain in document order.", location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/coverage.xsd', 172, 1))
_Namespace_gml.addCategoryObject('elementBinding', CoverageMappingRule.name().localName(), CoverageMappingRule)

GridFunction = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'GridFunction'), GridFunctionType, documentation='gml:GridFunction provides an explicit mapping rule for grid geometries, i.e. the domain shall be a geometry of type grid.  It describes the mapping of grid posts (discrete point grid coverage) or grid cells (discrete surface coverage) to the values in the range set.\nThe gml:startPoint is the index position of a point in the grid that is mapped to the first point in the range set (this is also the index position of the first grid post).  If the gml:startPoint property is omitted the gml:startPoint is assumed to be equal to the value of gml:low in the gml:Grid geometry. Subsequent points in the mapping are determined by the value of the gml:sequenceRule.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/coverage.xsd', 185, 1))
_Namespace_gml.addCategoryObject('elementBinding', GridFunction.name().localName(), GridFunction)

anchorDefinition = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'anchorDefinition'), CodeType, documentation='gml:anchorDefinition is a description, possibly including coordinates, of the definition used to anchor the datum to the Earth. Also known as the "origin", especially for engineering and image datums. The codeSpace attribute may be used to reference a source of more detailed on this point or surface, or on a set of such descriptions.\n-\tFor a geodetic datum, this point is also known as the fundamental point, which is traditionally the point where the relationship between geoid and ellipsoid is defined. In some cases, the "fundamental point" may consist of a number of points. In those cases, the parameters defining the geoid/ellipsoid relationship have been averaged for these points, and the averages adopted as the datum definition.\n-\tFor an engineering datum, the anchor definition may be a physical point, or it may be a point with defined coordinates in another CRS.may\n-\tFor an image datum, the anchor definition is usually either the centre of the image or the corner of the image.\n-\tFor a temporal datum, this attribute is not defined. Instead of the anchor definition, a temporal datum carries a separate time origin of type DateTime.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/datums.xsd', 38, 1))
_Namespace_gml.addCategoryObject('elementBinding', anchorDefinition.name().localName(), anchorDefinition)

secondDefiningParameter = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'secondDefiningParameter'), CTD_ANON, documentation='gml:secondDefiningParameter is a property containing the definition of the second parameter that defines the shape of an ellipsoid. An ellipsoid requires two defining parameters: semi-major axis and inverse flattening or semi-major axis and semi-minor axis. When the reference body is a sphere rather than an ellipsoid, only a single defining parameter is required, namely the radius of the sphere; in that case, the semi-major axis "degenerates" into the radius of the sphere.\nThe inverseFlattening element contains the inverse flattening value of the ellipsoid. This value is a scale factor (or ratio). It uses gml:LengthType with the restriction that the unit of measure referenced by the uom attribute must be suitable for a scale factor, such as percent, permil, or parts-per-million.\nThe semiMinorAxis element contains the length of the semi-minor axis of the ellipsoid. When the isSphere element is included, the ellipsoid is degenerate and is actually a sphere. The sphere is completely defined by the semi-major axis, which is the radius of the sphere.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/datums.xsd', 115, 1))
_Namespace_gml.addCategoryObject('elementBinding', secondDefiningParameter.name().localName(), secondDefiningParameter)

SecondDefiningParameter = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'SecondDefiningParameter'), CTD_ANON_, location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/datums.xsd', 127, 1))
_Namespace_gml.addCategoryObject('elementBinding', SecondDefiningParameter.name().localName(), SecondDefiningParameter)

anchorPoint = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'anchorPoint'), CodeType, documentation='', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/deprecatedTypes.xsd', 18, 1))
_Namespace_gml.addCategoryObject('elementBinding', anchorPoint.name().localName(), anchorPoint)

