AffinePlacement = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'AffinePlacement'), AffinePlacementType, documentation='location, refDirection, inDimension and outDimension have the same meaning as specified in ISO 19107:2003, 6.4.21.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/geometryPrimitives.xsd', 441, 1))
