AbstractSurfacePatch = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'AbstractSurfacePatch'), AbstractSurfacePatchType, abstract=pyxb.binding.datatypes.boolean(1), documentation='A surface patch defines a homogenuous portion of a surface. \nThe AbstractSurfacePatch element is the abstract head of the substituition group for all surface patch elements describing a continuous portion of a surface.\nAll surface patches shall have an attribute interpolation (declared in the types derived from gml:AbstractSurfacePatchType) specifying the interpolation mechanism used for the patch using gml:SurfaceInterpolationType.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/geometryPrimitives.xsd', 534, 1))
_Namespace_gml.addCategoryObject('elementBinding', AbstractSurfacePatch.name().localName(), AbstractSurfacePatch)

patches = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'patches'), SurfacePatchArrayPropertyType, documentation='The patches property element contains the sequence of surface patches. The order of the elements is significant and shall be preserved when processing the array.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/geometryPrimitives.xsd', 549, 1))
