_Namespace_gml.addCategoryObject('elementBinding', Null.name().localName(), Null)

degrees = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'degrees'), DegreesType, documentation='', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/deprecatedTypes.xsd', 554, 1))
_Namespace_gml.addCategoryObject('elementBinding', degrees.name().localName(), degrees)

Bag = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'Bag'), BagType, documentation='', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/deprecatedTypes.xsd', 677, 1))
_Namespace_gml.addCategoryObject('elementBinding', Bag.name().localName(), Bag)

Array = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'Array'), ArrayType, documentation='', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/deprecatedTypes.xsd', 695, 1))
_Namespace_gml.addCategoryObject('elementBinding', Array.name().localName(), Array)

GenericMetaData = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'GenericMetaData'), GenericMetaDataType, documentation='', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/deprecatedTypes.xsd', 734, 1))
_Namespace_gml.addCategoryObject('elementBinding', GenericMetaData.name().localName(), GenericMetaData)

AbstractTimeSlice = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'AbstractTimeSlice'), AbstractTimeSliceType, abstract=pyxb.binding.datatypes.boolean(1), documentation='To describe an event — an action that occurs at an instant or over an interval of time — GML provides the gml:AbtractTimeSlice element. A timeslice encapsulates the time-varying properties of a dynamic feature -- it shall be extended to represent a time stamped projection of a specific feature. The gml:dataSource property describes how the temporal data was acquired.\nA gml:AbstractTimeSlice instance is a GML object that encapsulates updates of the dynamic—or volatile—properties that reflect some change event; it thus includes only those feature properties that have actually changed due to some process.\ngml:AbstractTimeSlice basically provides a facility for attribute-level time stamping, in contrast to the object-level time stamping of dynamic feature instances. \nThe time slice can thus be viewed as event or process-oriented, whereas a snapshot is more state or structure-oriented. A timeslice has richer causality, whereas a snapshot merely portrays the status of the whole. \n', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/dynamicFeature.xsd', 78, 1))
_Namespace_gml.addCategoryObject('elementBinding', AbstractTimeSlice.name().localName(), AbstractTimeSlice)

AbstractFeature = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'AbstractFeature'), AbstractFeatureType, abstract=pyxb.binding.datatypes.boolean(1), documentation='This abstract element serves as the head of a substitution group which may contain any elements whose content model is derived from gml:AbstractFeatureType.  This may be used as a variable in the construction of content models.  \ngml:AbstractFeature may be thought of as "anything that is a GML feature" and may be used to define variables or templates in which the value of a GML property is "any feature". This occurs in particular in a GML feature collection where the feature member properties contain one or multiple copies of gml:AbstractFeature respectively.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/feature.xsd', 32, 1))
_Namespace_gml.addCategoryObject('elementBinding', AbstractFeature.name().localName(), AbstractFeature)

AbstractGeometry = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'AbstractGeometry'), AbstractGeometryType, abstract=pyxb.binding.datatypes.boolean(1), documentation='The AbstractGeometry element is the abstract head of the substitution group for all geometry elements of GML. This includes pre-defined and user-defined geometry elements. Any geometry element shall be a direct or indirect extension/restriction of AbstractGeometryType and shall be directly or indirectly in the substitution group of AbstractGeometry.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/geometryBasic0d1d.xsd', 50, 1))
_Namespace_gml.addCategoryObject('elementBinding', AbstractGeometry.name().localName(), AbstractGeometry)

pos = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'pos'), DirectPositionType, location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/geometryBasic0d1d.xsd', 87, 1))
_Namespace_gml.addCategoryObject('elementBinding', pos.name().localName(), pos)

posList = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'posList'), DirectPositionListType, location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/geometryBasic0d1d.xsd', 102, 1))
_Namespace_gml.addCategoryObject('elementBinding', posList.name().localName(), posList)

Envelope = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'Envelope'), EnvelopeType, documentation='Envelope defines an extent using a pair of positions defining opposite corners in arbitrary dimensions. The first direct position is the "lower corner" (a coordinate position consisting of all the minimal ordinates for each dimension for all points within the envelope), the second one the "upper corner" (a coordinate position consisting of all the maximal ordinates for each dimension for all points within the envelope).\nThe use of the properties "coordinates" and "pos" has been deprecated. The explicitly named properties "lowerCorner" and "upperCorner" shall be used instead.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/geometryBasic0d1d.xsd', 148, 1))
_Namespace_gml.addCategoryObject('elementBinding', Envelope.name().localName(), Envelope)

LineStringSegment = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'LineStringSegment'), LineStringSegmentType, documentation='A LineStringSegment is a curve segment that is defined by two or more control points including the start and end point, with linear interpolation between them.\nThe content model follows the general pattern for the encoding of curve segments.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/geometryPrimitives.xsd', 114, 1))
_Namespace_gml.addCategoryObject('elementBinding', LineStringSegment.name().localName(), LineStringSegment)

ArcString = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'ArcString'), ArcStringType, documentation='An ArcString is a curve segment that uses three-point circular arc interpolation ("circularArc3Points"). The number of arcs in the arc string may be explicitly stated in the attribute numArc. The number of control points in the arc string shall be 2 * numArc + 1.\nThe content model follows the general pattern for the encoding of curve segments.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/geometryPrimitives.xsd', 139, 1))
_Namespace_gml.addCategoryObject('elementBinding', ArcString.name().localName(), ArcString)

ArcStringByBulge = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'ArcStringByBulge'), ArcStringByBulgeType, documentation='This variant of the arc computes the mid points of the arcs instead of storing the coordinates directly. The control point sequence consists of the start and end points of each arc plus the bulge (see ISO 19107:2003, 6.4.17.2). The normal is a vector normal (perpendicular) to the chord of the arc (see ISO 19107:2003, 6.4.17.4).\nThe interpolation is fixed as "circularArc2PointWithBulge".\nThe number of arcs in the arc string may be explicitly stated in the attribute numArc. The number of control points in the arc string shall be numArc + 1.\nThe content model follows the general pattern for the encoding of curve segments.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/geometryPrimitives.xsd', 199, 1))
_Namespace_gml.addCategoryObject('elementBinding', ArcStringByBulge.name().localName(), ArcStringByBulge)

ArcByCenterPoint = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'ArcByCenterPoint'), ArcByCenterPointType, documentation='This variant of the arc requires that the points on the arc shall be computed instead of storing the coordinates directly. The single control point is the center point of the arc plus the radius and the bearing at start and end. This representation can be used only in 2D.\nThe element radius specifies the radius of the arc.\nThe element startAngle specifies the bearing of the arc at the start.\nThe element endAngle specifies the bearing of the arc at the end.\nThe interpolation is fixed as "circularArcCenterPointWithRadius".\nSince this type describes always a single arc, the attribute "numArc" is fixed to "1".\nThe content model follows the general pattern for the encoding of curve segments.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/geometryPrimitives.xsd', 255, 1))
_Namespace_gml.addCategoryObject('elementBinding', ArcByCenterPoint.name().localName(), ArcByCenterPoint)

CubicSpline = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'CubicSpline'), CubicSplineType, documentation='The number of control points shall be at least three.\nvectorAtStart is the unit tangent vector at the start point of the spline. vectorAtEnd is the unit tangent vector at the end point of the spline. Only the direction of the vectors shall be used to determine the shape of the cubic spline, not their length.\ninterpolation is fixed as "cubicSpline".\ndegree shall be the degree of the polynomial used for the interpolation in this spline. Therefore the degree for a cubic spline is fixed to "3".\nThe content model follows the general pattern for the encoding of curve segments.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/geometryPrimitives.xsd', 310, 1))
_Namespace_gml.addCategoryObject('elementBinding', CubicSpline.name().localName(), CubicSpline)

BSpline = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'BSpline'), BSplineType, documentation='A B-Spline is a piecewise parametric polynomial or rational curve described in terms of control points and basis functions as specified in ISO 19107:2003, 6.4.30. Therefore, interpolation may be either "polynomialSpline" or "rationalSpline" depending on the interpolation type; default is "polynomialSpline".\ndegree shall be the degree of the polynomial used for interpolation in this spline.\nknot shall be the sequence of distinct knots used to define the spline basis functions (see ISO 19107:2003, 6.4.26.2).\nThe attribute isPolynomial shall be set to "true" if this is a polynomial spline (see ISO 19107:2003, 6.4.30.5).\nThe attribute knotType shall provide the type of knot distribution used in defining this spline (see ISO 19107:2003, 6.4.30.4).\nThe content model follows the general pattern for the encoding of curve segments.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/geometryPrimitives.xsd', 341, 1))
_Namespace_gml.addCategoryObject('elementBinding', BSpline.name().localName(), BSpline)

OffsetCurve = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'OffsetCurve'), OffsetCurveType, documentation='An offset curve is a curve at a constant distance from the basis curve. offsetBase is the base curve from which this curve is defined as an offset. distance and refDirection have the same meaning as specified in ISO 19107:2003, 6.4.23.\nThe content model follows the general pattern for the encoding of curve segments.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/geometryPrimitives.xsd', 427, 1))
_Namespace_gml.addCategoryObject('elementBinding', OffsetCurve.name().localName(), OffsetCurve)

Clothoid = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'Clothoid'), ClothoidType, documentation='A clothoid, or Cornu\'s spiral, is plane curve whose curvature is a fixed function of its length.\nrefLocation, startParameter, endParameter and scaleFactor have the same meaning as specified in ISO 19107:2003, 6.4.22.\ninterpolation is fixed as "clothoid".\nThe content model follows the general pattern for the encoding of curve segments.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/geometryPrimitives.xsd', 465, 1))
_Namespace_gml.addCategoryObject('elementBinding', Clothoid.name().localName(), Clothoid)

GeodesicString = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'GeodesicString'), GeodesicStringType, documentation='A sequence of geodesic segments. \nThe number of control points shall be at least two.\ninterpolation is fixed as "geodesic".\nThe content model follows the general pattern for the encoding of curve segments.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/geometryPrimitives.xsd', 484, 1))
_Namespace_gml.addCategoryObject('elementBinding', GeodesicString.name().localName(), GeodesicString)

PolygonPatch = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'PolygonPatch'), PolygonPatchType, documentation='A gml:PolygonPatch is a surface patch that is defined by a set of boundary curves and an underlying surface to which these curves adhere. The curves shall be coplanar and the polygon uses planar interpolation in its interior. \ninterpolation is fixed to "planar", i.e. an interpolation shall return points on a single plane. The boundary of the patch shall be contained within that plane.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/geometryPrimitives.xsd', 582, 1))
_Namespace_gml.addCategoryObject('elementBinding', PolygonPatch.name().localName(), PolygonPatch)

Triangle = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'Triangle'), TriangleType, documentation='gml:Triangle represents a triangle as a surface patch with an outer boundary consisting of a linear ring. Note that this is a polygon (subtype) with no inner boundaries. The number of points in the linear ring shall be four.\nThe ring (element exterior) shall be a gml:LinearRing and shall form a triangle, the first and the last position shall be coincident.\ninterpolation is fixed to "planar", i.e. an interpolation shall return points on a single plane. The boundary of the patch shall be contained within that plane.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/geometryPrimitives.xsd', 598, 1))
_Namespace_gml.addCategoryObject('elementBinding', Triangle.name().localName(), Triangle)

Rectangle = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'Rectangle'), RectangleType, documentation='gml:Rectangle represents a rectangle as a surface patch with an outer boundary consisting of a linear ring. Note that this is a polygon (subtype) with no inner boundaries. The number of points in the linear ring shall be five.\nThe ring (element exterior) shall be a gml:LinearRing and shall form a rectangle; the first and the last position shall be coincident.\ninterpolation is fixed to "planar", i.e. an interpolation shall return points on a single plane. The boundary of the patch shall be contained within that plane.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/geometryPrimitives.xsd', 615, 1))
_Namespace_gml.addCategoryObject('elementBinding', Rectangle.name().localName(), Rectangle)

AbstractParametricCurveSurface = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'AbstractParametricCurveSurface'), AbstractParametricCurveSurfaceType, abstract=pyxb.binding.datatypes.boolean(1), documentation='The element provides a substitution group head for the surface patches based on parametric curves. All properties are specified in the derived subtypes. All derived subtypes shall conform to the constraints specified in ISO 19107:2003, 6.4.40.\nIf provided, the aggregationType attribute shall have the value "set".', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/geometryPrimitives.xsd', 673, 1))
_Namespace_gml.addCategoryObject('elementBinding', AbstractParametricCurveSurface.name().localName(), AbstractParametricCurveSurface)

identifier = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'identifier'), CodeWithAuthorityType, documentation='Often, a special identifier is assigned to an object by the maintaining authority with the intention that it is used in references to the object For such cases, the codeSpace shall be provided. That identifier is usually unique either globally or within an application domain. gml:identifier is a pre-defined property for such identifiers.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/gmlBase.xsd', 132, 1))
_Namespace_gml.addCategoryObject('elementBinding', identifier.name().localName(), identifier)

AbstractImplicitGeometry = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'AbstractImplicitGeometry'), AbstractGeometryType, abstract=pyxb.binding.datatypes.boolean(1), location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/grids.xsd', 22, 1))
_Namespace_gml.addCategoryObject('elementBinding', AbstractImplicitGeometry.name().localName(), AbstractImplicitGeometry)

AbstractTimeObject = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'AbstractTimeObject'), AbstractTimeObjectType, abstract=pyxb.binding.datatypes.boolean(1), documentation='gml:AbstractTimeObject acts as the head of a substitution group for all temporal primitives and complexes.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/temporal.xsd', 18, 1))
_Namespace_gml.addCategoryObject('elementBinding', AbstractTimeObject.name().localName(), AbstractTimeObject)

timePosition = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'timePosition'), TimePositionType, documentation='This element is used directly as a property of gml:TimeInstant (see 15.2.2.3), and may also be used in application schemas.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/temporal.xsd', 215, 1))
_Namespace_gml.addCategoryObject('elementBinding', timePosition.name().localName(), timePosition)

AbstractTopology = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'AbstractTopology'), AbstractTopologyType, abstract=pyxb.binding.datatypes.boolean(1), location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/topology.xsd', 25, 2))
_Namespace_gml.addCategoryObject('elementBinding', AbstractTopology.name().localName(), AbstractTopology)

CompositeValue = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'CompositeValue'), CompositeValueType, documentation='gml:CompositeValue is an aggregate value built from other values . It contains zero or an arbitrary number of gml:valueComponent elements, and zero or one gml:valueComponents property elements.  It may be used for strongly coupled aggregates (vectors, tensors) or for arbitrary collections of values.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/valueObjects.xsd', 125, 1))
_Namespace_gml.addCategoryObject('elementBinding', CompositeValue.name().localName(), CompositeValue)

Measure = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gco, 'Measure'), MeasureType, location=pyxb.utils.utility.Location('http://schemas.opengis.net/iso/19139/20070417/gco/basicTypes.xsd', 113, 1))
_Namespace_gco.addCategoryObject('elementBinding', Measure.name().localName(), Measure)

