coordinateOperationAccuracy = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'coordinateOperationAccuracy'), CTD_ANON_6, documentation='gml:coordinateOperationAccuracy is an association role to a DQ_PositionalAccuracy object as encoded in ISO/TS 19139, either referencing or containing the definition of that positional accuracy. That object contains an estimate of the impact of this coordinate operation on point accuracy. That is, it gives position error estimates for the target coordinates of this coordinate operation, assuming no errors in the source coordinates.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/coordinateOperations.xsd', 48, 1))
_Namespace_gml.addCategoryObject('elementBinding', coordinateOperationAccuracy.name().localName(), coordinateOperationAccuracy)

sourceCRS = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'sourceCRS'), CRSPropertyType, documentation='gml:sourceCRS is an association role to the source CRS (coordinate reference system) of this coordinate operation.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/coordinateOperations.xsd', 59, 1))
_Namespace_gml.addCategoryObject('elementBinding', sourceCRS.name().localName(), sourceCRS)

