_Namespace_gml.addCategoryObject('elementBinding', targetCRS.name().localName(), targetCRS)

coordOperation = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'coordOperation'), CoordinateOperationPropertyType, documentation='gml:coordOperation is an association role to a coordinate operation.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/coordinateOperations.xsd', 176, 1))
_Namespace_gml.addCategoryObject('elementBinding', coordOperation.name().localName(), coordOperation)

method = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'method'), OperationMethodPropertyType, documentation='gml:method is an association role to the operation method used by a coordinate operation.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/coordinateOperations.xsd', 238, 1))
_Namespace_gml.addCategoryObject('elementBinding', method.name().localName(), method)

value = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'value'), MeasureType, documentation='gml:value is a numeric value of an operation parameter, with its associated unit of measure.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/coordinateOperations.xsd', 324, 1))
_Namespace_gml.addCategoryObject('elementBinding', value.name().localName(), value)

valueList = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'valueList'), MeasureListType, documentation='gml:valueList is an ordered sequence of two or more numeric values of an operation parameter list, where each value has the same associated unit of measure. An element of this type contains a space-separated sequence of double values.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/coordinateOperations.xsd', 344, 1))
_Namespace_gml.addCategoryObject('elementBinding', valueList.name().localName(), valueList)

operationParameter = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'operationParameter'), OperationParameterPropertyType, documentation='gml:operationParameter is an association role to the operation parameter of which this is a value.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/coordinateOperations.xsd', 359, 1))
_Namespace_gml.addCategoryObject('elementBinding', operationParameter.name().localName(), operationParameter)

group = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'group'), OperationParameterGroupPropertyType, documentation='gml:group is an association role to the operation parameter group for which this element provides parameter values.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/coordinateOperations.xsd', 380, 1))
_Namespace_gml.addCategoryObject('elementBinding', group.name().localName(), group)

formulaCitation = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'formulaCitation'), CTD_ANON_7, documentation='gml:formulaCitation provides a reference to a publication giving the formula(s) or procedure used by an coordinate operation method.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/coordinateOperations.xsd', 406, 1))
