_Namespace_gml.addCategoryObject('elementBinding', multiPointProperty.name().localName(), multiPointProperty)

multiCurveProperty = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'multiCurveProperty'), MultiCurvePropertyType, documentation='', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/deprecatedTypes.xsd', 1093, 1))
