multiSurfaceProperty = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'multiSurfaceProperty'), MultiSurfacePropertyType, documentation='', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/deprecatedTypes.xsd', 1098, 1))
