multiSolidProperty = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'multiSolidProperty'), MultiSolidPropertyType, documentation='', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/deprecatedTypes.xsd', 1103, 1))
_Namespace_gml.addCategoryObject('elementBinding', multiSolidProperty.name().localName(), multiSolidProperty)

multiGeometryProperty = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'multiGeometryProperty'), MultiGeometryPropertyType, documentation='', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/deprecatedTypes.xsd', 1108, 1))
_Namespace_gml.addCategoryObject('elementBinding', multiGeometryProperty.name().localName(), multiGeometryProperty)

Definition = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'Definition'), DefinitionType, documentation='The basic gml:Definition element specifies a definition, which can be included in or referenced by a dictionary. \nThe content model for a generic definition is a derivation from gml:AbstractGMLType.  \nThe gml:description property element shall hold the definition if this can be captured in a simple text string, or the gml:descriptionReference property element may carry a link to a description elsewhere.\nThe gml:identifier element shall provide one identifier identifying this definition. The identifier shall be unique within the dictionaries using this definition. \nThe gml:name elements shall provide zero or more terms and synonyms for which this is the definition.\nThe gml:remarks element shall be used to hold additional textual information that is not conceptually part of the definition but is useful in understanding the definition.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/dictionary.xsd', 21, 1))
_Namespace_gml.addCategoryObject('elementBinding', Definition.name().localName(), Definition)

dictionaryEntry = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'dictionaryEntry'), DictionaryEntryType, documentation='This property element contains or refers to the definitions which are members of a dictionary. \nThe content model follows the standard GML property pattern, so a gml:dictionaryEntry may either contain or refer to a single gml:Definition. Since gml:Dictionary is substitutable for gml:Definition, the content of an entry may itself be a lower level dictionary. \nNote that if the value is provided by reference, this definition does not carry a handle (gml:id) in this context, so does not allow external references to this specific definition in this context.  When used in this way the referenced definition will usually be in a dictionary in the same XML document.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/dictionary.xsd', 73, 1))
_Namespace_gml.addCategoryObject('elementBinding', dictionaryEntry.name().localName(), dictionaryEntry)

direction = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'direction'), DirectionPropertyType, documentation='The property gml:direction is intended as a pre-defined property expressing a direction to be assigned to features defined in a GML application schema.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/direction.xsd', 15, 1))
_Namespace_gml.addCategoryObject('elementBinding', direction.name().localName(), direction)

dataSource = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'dataSource'), StringOrRefType, documentation='Evidence is represented by a simple gml:dataSource or gml:dataSourceReference property that indicates the source of the temporal data. The remote link attributes of the gml:dataSource element have been deprecated along with its current type.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/dynamicFeature.xsd', 17, 1))
_Namespace_gml.addCategoryObject('elementBinding', dataSource.name().localName(), dataSource)

dataSourceReference = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'dataSourceReference'), ReferenceType, documentation='Evidence is represented by a simple gml:dataSource or gml:dataSourceReference property that indicates the source of the temporal data.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/dynamicFeature.xsd', 22, 1))
_Namespace_gml.addCategoryObject('elementBinding', dataSourceReference.name().localName(), dataSourceReference)

DynamicFeature = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'DynamicFeature'), DynamicFeatureType, documentation="States are captured by time-stamped instances of a feature. The content model extends the standard gml:AbstractFeatureType with the gml:dynamicProperties model group.\nEach time-stamped instance represents a 'snapshot' of a feature. The dynamic feature classes will normally be extended to suit particular applications.  A dynamic feature bears either a time stamp or a history.", location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/dynamicFeature.xsd', 38, 1))
_Namespace_gml.addCategoryObject('elementBinding', DynamicFeature.name().localName(), DynamicFeature)

dynamicMembers = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'dynamicMembers'), DynamicFeatureMemberType, location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/dynamicFeature.xsd', 67, 1))
_Namespace_gml.addCategoryObject('elementBinding', dynamicMembers.name().localName(), dynamicMembers)

boundedBy = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'boundedBy'), BoundingShapeType, nillable=pyxb.binding.datatypes.boolean(1), documentation='This property describes the minimum bounding box or rectangle that encloses the entire feature.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/feature.xsd', 45, 1))
_Namespace_gml.addCategoryObject('elementBinding', boundedBy.name().localName(), boundedBy)

EnvelopeWithTimePeriod = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'EnvelopeWithTimePeriod'), EnvelopeWithTimePeriodType, documentation='gml:EnvelopeWithTimePeriod is provided for envelopes that include a temporal extent. It adds two time position properties, gml:beginPosition and gml:endPosition, which describe the extent of a time-envelope.  \nSince gml:EnvelopeWithTimePeriod is assigned to the substitution group headed by gml:Envelope, it may be used whenever gml:Envelope is valid.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/feature.xsd', 59, 1))
_Namespace_gml.addCategoryObject('elementBinding', EnvelopeWithTimePeriod.name().localName(), EnvelopeWithTimePeriod)

locationReference = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'locationReference'), ReferenceType, documentation='The gml:locationReference property element is a convenience property where the text value referenced by the xlink:href attribute describes the location of the feature.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/feature.xsd', 81, 1))
_Namespace_gml.addCategoryObject('elementBinding', locationReference.name().localName(), locationReference)

AbstractGeometricAggregate = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'AbstractGeometricAggregate'), AbstractGeometricAggregateType, abstract=pyxb.binding.datatypes.boolean(1), documentation='gml:AbstractGeometricAggregate is the abstract head of the substitution group for all geometric aggregates.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/geometryAggregates.xsd', 22, 1))
_Namespace_gml.addCategoryObject('elementBinding', AbstractGeometricAggregate.name().localName(), AbstractGeometricAggregate)

geometryMember = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'geometryMember'), GeometryPropertyType, documentation='This property element either references a geometry element via the XLink-attributes or contains the geometry element.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/geometryAggregates.xsd', 43, 1))
_Namespace_gml.addCategoryObject('elementBinding', geometryMember.name().localName(), geometryMember)

pointMember = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'pointMember'), PointPropertyType, documentation='This property element either references a Point via the XLink-attributes or contains the Point element.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/geometryAggregates.xsd', 79, 1))
_Namespace_gml.addCategoryObject('elementBinding', pointMember.name().localName(), pointMember)

solidMember = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'solidMember'), SolidPropertyType, documentation='This property element either references a solid via the XLink-attributes or contains the solid element. A solid element is any element, which is substitutable for gml:AbstractSolid.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/geometryAggregates.xsd', 177, 1))
_Namespace_gml.addCategoryObject('elementBinding', solidMember.name().localName(), solidMember)

vector = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'vector'), VectorType, location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/geometryBasic0d1d.xsd', 132, 1))
_Namespace_gml.addCategoryObject('elementBinding', vector.name().localName(), vector)

AbstractGeometricPrimitive = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'AbstractGeometricPrimitive'), AbstractGeometricPrimitiveType, abstract=pyxb.binding.datatypes.boolean(1), documentation='The AbstractGeometricPrimitive element is the abstract head of the substitution group for all (pre- and user-defined) geometric primitives.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/geometryBasic0d1d.xsd', 162, 1))
_Namespace_gml.addCategoryObject('elementBinding', AbstractGeometricPrimitive.name().localName(), AbstractGeometricPrimitive)

pointProperty = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'pointProperty'), PointPropertyType, documentation='This property element either references a point via the XLink-attributes or contains the point element. pointProperty is the predefined property which may be used by GML Application Schemas whenever a GML feature has a property with a value that is substitutable for Point.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/geometryBasic0d1d.xsd', 204, 1))
_Namespace_gml.addCategoryObject('elementBinding', pointProperty.name().localName(), pointProperty)

curveProperty = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'curveProperty'), CurvePropertyType, documentation='This property element either references a curve via the XLink-attributes or contains the curve element. curveProperty is the predefined property which may be used by GML Application Schemas whenever a GML feature has a property with a value that is substitutable for AbstractCurve.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/geometryBasic0d1d.xsd', 241, 1))
_Namespace_gml.addCategoryObject('elementBinding', curveProperty.name().localName(), curveProperty)

surfaceProperty = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'surfaceProperty'), SurfacePropertyType, documentation='This property element either references a surface via the XLink-attributes or contains the surface element. surfaceProperty is the predefined property which may be used by GML Application Schemas whenever a GML feature has a property with a value that is substitutable for AbstractSurface.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/geometryBasic2d.xsd', 37, 1))
_Namespace_gml.addCategoryObject('elementBinding', surfaceProperty.name().localName(), surfaceProperty)

GeometricComplex = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'GeometricComplex'), GeometricComplexType, location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/geometryComplexes.xsd', 28, 1))
_Namespace_gml.addCategoryObject('elementBinding', GeometricComplex.name().localName(), GeometricComplex)

baseCurve = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'baseCurve'), CurvePropertyType, documentation='The property baseCurve references or contains the base curve, i.e. it either references the base curve via the XLink-attributes or contains the curve element. A curve element is any element which is substitutable for AbstractCurve. The base curve has positive orientation.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/geometryPrimitives.xsd', 42, 1))
_Namespace_gml.addCategoryObject('elementBinding', baseCurve.name().localName(), baseCurve)

Arc = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'Arc'), ArcType, documentation='An Arc is an arc string with only one arc unit, i.e. three control points including the start and end point. As arc is an arc string consisting of a single arc, the attribute "numArc" is fixed to "1".', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/geometryPrimitives.xsd', 163, 1))
_Namespace_gml.addCategoryObject('elementBinding', Arc.name().localName(), Arc)

ArcByBulge = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'ArcByBulge'), ArcByBulgeType, documentation='An ArcByBulge is an arc string with only one arc unit, i.e. two control points, one bulge and one normal vector.\nAs arc is an arc string consisting of a single arc, the attribute "numArc" is fixed to "1".', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/geometryPrimitives.xsd', 227, 1))
_Namespace_gml.addCategoryObject('elementBinding', ArcByBulge.name().localName(), ArcByBulge)

CircleByCenterPoint = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'CircleByCenterPoint'), CircleByCenterPointType, documentation='A gml:CircleByCenterPoint is an gml:ArcByCenterPoint with identical start and end angle to form a full circle. Again, this representation can be used only in 2D.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/geometryPrimitives.xsd', 284, 1))
_Namespace_gml.addCategoryObject('elementBinding', CircleByCenterPoint.name().localName(), CircleByCenterPoint)

Bezier = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'Bezier'), BezierType, documentation='Bezier curves are polynomial splines that use Bezier or Bernstein polynomials for interpolation purposes. It is a special case of the B-Spline curve with two knots.\ndegree shall be the degree of the polynomial used for interpolation in this spline.\nknot shall be the sequence of distinct knots used to define the spline basis functions.\ninterpolation is fixed as "polynomialSpline".\nisPolynomial is fixed as "true".\nknotType is not relevant for Bezier curve segments.\n', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/geometryPrimitives.xsd', 405, 1))
_Namespace_gml.addCategoryObject('elementBinding', Bezier.name().localName(), Bezier)

Geodesic = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'Geodesic'), GeodesicType, location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/geometryPrimitives.xsd', 497, 1))
_Namespace_gml.addCategoryObject('elementBinding', Geodesic.name().localName(), Geodesic)

baseSurface = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'baseSurface'), SurfacePropertyType, documentation='The property baseSurface references or contains the base surface. The property baseSurface either references the base surface via the XLink-attributes or contains the surface element. A surface element is any element which is substitutable for gml:AbstractSurface. The base surface has positive orientation.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/geometryPrimitives.xsd', 523, 1))
_Namespace_gml.addCategoryObject('elementBinding', baseSurface.name().localName(), baseSurface)

curveMember = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'curveMember'), CurvePropertyType, location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/geometryPrimitives.xsd', 639, 1))
_Namespace_gml.addCategoryObject('elementBinding', curveMember.name().localName(), curveMember)

AbstractGriddedSurface = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'AbstractGriddedSurface'), AbstractGriddedSurfaceType, abstract=pyxb.binding.datatypes.boolean(1), documentation='if provided, rows gives the number of rows, columns the number of columns in the parameter grid. The parameter grid is represented by an instance of the gml:PointGrid group.\nThe element provides a substitution group head for the surface patches based on a grid. All derived subtypes shall conform to the constraints specified in ISO 19107:2003, 6.4.41.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/geometryPrimitives.xsd', 690, 1))
_Namespace_gml.addCategoryObject('elementBinding', AbstractGriddedSurface.name().localName(), AbstractGriddedSurface)

solidProperty = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'solidProperty'), SolidPropertyType, documentation='This property element either references a solid via the XLink-attributes or contains the solid element. solidProperty is the predefined property which may be used by GML Application Schemas whenever a GML feature has a property with a value that is substitutable for AbstractSolid.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/geometryPrimitives.xsd', 790, 1))
_Namespace_gml.addCategoryObject('elementBinding', solidProperty.name().localName(), solidProperty)

surfaceMember = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'surfaceMember'), SurfacePropertyType, documentation='This property element either references a surface via the XLink-attributes or contains the surface element. A surface element is any element, which is substitutable for gml:AbstractSurface.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/geometryPrimitives.xsd', 837, 1))
_Namespace_gml.addCategoryObject('elementBinding', surfaceMember.name().localName(), surfaceMember)

abstractAssociationRole = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'abstractAssociationRole'), AssociationRoleType, abstract=pyxb.binding.datatypes.boolean(1), documentation='Applying this pattern shall restrict the multiplicity of objects in a property element using this content model to exactly one. An instance of this type shall contain an element representing an object, or serve as a pointer to a remote object.\nApplying the pattern to define an application schema specific property type allows to restrict\n-\tthe inline object to specified object types, \n-\tthe encoding to "by-reference only" (see 7.2.3.7),\n-\tthe encoding to "inline only" (see 7.2.3.8).', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/gmlBase.xsd', 58, 1))
_Namespace_gml.addCategoryObject('elementBinding', abstractAssociationRole.name().localName(), abstractAssociationRole)

abstractStrictAssociationRole = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'abstractStrictAssociationRole'), AssociationRoleType, abstract=pyxb.binding.datatypes.boolean(1), documentation='This element shows how an element \n\tdeclaration may include a Schematron constraint to limit the property to act \n\tin either inline or by-reference mode, but not both.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/gmlBase.xsd', 81, 1))
_Namespace_gml.addCategoryObject('elementBinding', abstractStrictAssociationRole.name().localName(), abstractStrictAssociationRole)

abstractReference = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'abstractReference'), ReferenceType, abstract=pyxb.binding.datatypes.boolean(1), documentation='gml:abstractReference may be used as the head of a subtitution group of more specific elements providing a value by-reference.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/gmlBase.xsd', 88, 1))
_Namespace_gml.addCategoryObject('elementBinding', abstractReference.name().localName(), abstractReference)

description = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'description'), StringOrRefType, documentation='The value of this property is a text description of the object. gml:description uses gml:StringOrRefType as its content model, so it may contain a simple text string content, or carry a reference to an external description. The use of gml:description to reference an external description has been deprecated and replaced by the gml:descriptionReference property.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/gmlBase.xsd', 117, 1))
_Namespace_gml.addCategoryObject('elementBinding', description.name().localName(), description)

descriptionReference = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'descriptionReference'), ReferenceType, documentation='The value of this property is a remote text description of the object. The xlink:href attribute of the gml:descriptionReference property references the external description.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/gmlBase.xsd', 122, 1))
_Namespace_gml.addCategoryObject('elementBinding', descriptionReference.name().localName(), descriptionReference)

Grid = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'Grid'), GridType, documentation='The gml:Grid implicitly defines an unrectified grid, which is a network composed of two or more sets of curves in which the members of each set intersect the members of the other sets in an algorithmic way.  The region of interest within the grid is given in terms of its gml:limits, being the grid coordinates of  diagonally opposed corners of a rectangular region.  gml:axisLabels is provided with a list of labels of the axes of the grid (gml:axisName has been deprecated). gml:dimension specifies the dimension of the grid.  \nThe gml:limits element contains a single gml:GridEnvelope. The gml:low and gml:high property elements of the envelope are each integerLists, which are coordinate tuples, the coordinates being measured as offsets from the origin of the grid along each axis, of the diagonally opposing corners of a "rectangular" region of interest.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/grids.xsd', 16, 1))
_Namespace_gml.addCategoryObject('elementBinding', Grid.name().localName(), Grid)

measure = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'measure'), MeasureType, documentation='The value of a physical quantity, together with its unit.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/measures.xsd', 15, 1))
_Namespace_gml.addCategoryObject('elementBinding', measure.name().localName(), measure)

Observation = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'Observation'), ObservationType, documentation='The content model is a straightforward extension of gml:AbstractFeatureType; it automatically has the gml:identifier, gml:description, gml:descriptionReference, gml:name, and gml:boundedBy properties. \nThe gml:validTime element describes the time of the observation. Note that this may be a time instant or a time period.\nThe gml:using property contains or references a description of a sensor, instrument or procedure used for the observation.\nThe gml:target property contains or references the specimen, region or station which is the object of the observation. This property is particularly useful for remote observations, such as photographs, where a generic location property might apply to the location of the camera or the location of the field of view, and thus may be ambiguous.  \nThe gml:subject element is provided as a convenient synonym for gml:target. This is the term commonly used in phtotography.  \nThe gml:resultOf property indicates the result of the observation.  The value may be inline, or a reference to a value elsewhere.\n', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/observation.xsd', 18, 1))
_Namespace_gml.addCategoryObject('elementBinding', Observation.name().localName(), Observation)

using = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'using'), ProcedurePropertyType, location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/observation.xsd', 41, 1))
_Namespace_gml.addCategoryObject('elementBinding', using.name().localName(), using)

target = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'target'), TargetPropertyType, location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/observation.xsd', 49, 1))
_Namespace_gml.addCategoryObject('elementBinding', target.name().localName(), target)

subject = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'subject'), TargetPropertyType, location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/observation.xsd', 50, 1))
_Namespace_gml.addCategoryObject('elementBinding', subject.name().localName(), subject)

resultOf = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'resultOf'), ResultType, location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/observation.xsd', 59, 1))
_Namespace_gml.addCategoryObject('elementBinding', resultOf.name().localName(), resultOf)

domainOfValidity = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'domainOfValidity'), CTD_ANON_8, documentation='The gml:domainOfValidity property implements an association role to an EX_Extent object as encoded in ISO/TS 19139, either referencing or containing the definition of that extent.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/referenceSystems.xsd', 45, 1))
_Namespace_gml.addCategoryObject('elementBinding', domainOfValidity.name().localName(), domainOfValidity)

AbstractTimePrimitive = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'AbstractTimePrimitive'), AbstractTimePrimitiveType, abstract=pyxb.binding.datatypes.boolean(1), documentation='gml:AbstractTimePrimitive acts as the head of a substitution group for geometric and topological temporal primitives.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/temporal.xsd', 28, 1))
_Namespace_gml.addCategoryObject('elementBinding', AbstractTimePrimitive.name().localName(), AbstractTimePrimitive)

validTime = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'validTime'), TimePrimitivePropertyType, documentation='gml:validTime is a convenience property element.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/temporal.xsd', 52, 1))
_Namespace_gml.addCategoryObject('elementBinding', validTime.name().localName(), validTime)

AbstractTimeComplex = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'AbstractTimeComplex'), AbstractTimeComplexType, abstract=pyxb.binding.datatypes.boolean(1), documentation='gml:AbstractTimeComplex is an aggregation of temporal primitives and acts as the head of a substitution group for temporal complexes.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/temporal.xsd', 85, 1))
_Namespace_gml.addCategoryObject('elementBinding', AbstractTimeComplex.name().localName(), AbstractTimeComplex)

timeInterval = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'timeInterval'), TimeIntervalLengthType, documentation=' gml:timeInterval conforms to ISO 11404 which is based on floating point values for temporal length.\nISO 11404 syntax specifies the use of a positiveInteger together with appropriate values for radix and factor. The resolution of the time interval is to one radix ^(-factor) of the specified time unit.\nThe value of the unit is either selected from the units for time intervals from ISO 31-1:1992, or is another suitable unit.  The encoding is defined for GML in gml:TimeUnitType. The second component of this union type provides a method for indicating time units other than the six standard units given in the enumeration.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/temporal.xsd', 234, 1))
_Namespace_gml.addCategoryObject('elementBinding', timeInterval.name().localName(), timeInterval)

AbstractTopoPrimitive = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'AbstractTopoPrimitive'), AbstractTopoPrimitiveType, abstract=pyxb.binding.datatypes.boolean(1), documentation='gml:AbstractTopoPrimitive acts as the base type for all topological primitives. Topology primitives are the atomic (smallest possible) units of a topology complex. \nEach topology primitive may contain references to other topology primitives of codimension 2 or more (gml:isolated). Conversely, nodes may have faces as containers and nodes and edges may have solids as containers (gml:container).', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/topology.xsd', 31, 2))
_Namespace_gml.addCategoryObject('elementBinding', AbstractTopoPrimitive.name().localName(), AbstractTopoPrimitive)

directedNode = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'directedNode'), DirectedNodePropertyType, documentation='A gml:directedNode property element describes the boundary of topology edges and is used in the support of topological point features via the gml:TopoPoint expression, see below. The orientation attribute of type gml:SignType expresses the sense in which the included node is used: start ("-") or end ("+") node.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/topology.xsd', 91, 2))
_Namespace_gml.addCategoryObject('elementBinding', directedNode.name().localName(), directedNode)

directedEdge = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'directedEdge'), DirectedEdgePropertyType, documentation='A gml:directedEdge property element describes the boundary of topology faces, the coBoundary of topology nodes and is used in the support of topological line features via the gml:TopoCurve expression, see below. The orientation attribute of type gml:SignType expresses the sense in which the included edge is used, i.e. forward or reverse.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/topology.xsd', 126, 2))
_Namespace_gml.addCategoryObject('elementBinding', directedEdge.name().localName(), directedEdge)

directedFace = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'directedFace'), DirectedFacePropertyType, documentation='The gml:directedFace property element describes the boundary of topology solids, in the coBoundary of topology edges and is used in the support of surface features via the gml:TopoSurface expression, see below. The orientation attribute of type gml:SignType expresses the sense in which the included face is used i.e. inward or outward with respect to the surface normal in any geometric realisation.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/topology.xsd', 165, 2))
_Namespace_gml.addCategoryObject('elementBinding', directedFace.name().localName(), directedFace)

directedTopoSolid = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'directedTopoSolid'), DirectedTopoSolidPropertyType, documentation='The gml:directedSolid property element describes the coBoundary of topology faces and is used in the support of volume features via the gml:TopoVolume expression, see below. The orientation attribute of type gml:SignType expresses the sense in which the included solid appears in the face coboundary. In the context of a gml:TopoVolume the orientation attribute has no meaning.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/topology.xsd', 202, 2))
_Namespace_gml.addCategoryObject('elementBinding', directedTopoSolid.name().localName(), directedTopoSolid)

TopoPoint = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'TopoPoint'), TopoPointType, documentation='The intended use of gml:TopoPoint is to appear within a point feature to express the structural and possibly geometric relationships of this feature to other features via shared node definitions.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/topology.xsd', 224, 2))
_Namespace_gml.addCategoryObject('elementBinding', TopoPoint.name().localName(), TopoPoint)

TopoCurve = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'TopoCurve'), TopoCurveType, documentation='gml:TopoCurve represents a homogeneous topological expression, a sequence of directed edges, which if realised are isomorphic to a geometric curve primitive. The intended use of gml:TopoCurve is to appear within a line feature to express the structural and geometric relationships of this feature to other features via the shared edge definitions.\nIf provided, the aggregationType attribute shall have the value "sequence".', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/topology.xsd', 250, 2))
_Namespace_gml.addCategoryObject('elementBinding', TopoCurve.name().localName(), TopoCurve)

TopoSurface = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'TopoSurface'), TopoSurfaceType, documentation='gml:TopoSurface represents a homogeneous topological expression, a set of directed faces, which if realised are isomorphic to a geometric surface primitive. The intended use of gml:TopoSurface is to appear within a surface feature to express the structural and possibly geometric relationships of this surface feature to other features via the shared face definitions.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/topology.xsd', 277, 2))
_Namespace_gml.addCategoryObject('elementBinding', TopoSurface.name().localName(), TopoSurface)

TopoVolume = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'TopoVolume'), TopoVolumeType, documentation='gml:TopoVolume represents a homogeneous topological expression, a set of directed topologic solids, which if realised are isomorphic to a geometric solid primitive. The intended use of gml:TopoVolume is to appear within a solid feature to express the structural and geometric relationships of this solid feature to other features via the shared solid definitions.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/topology.xsd', 303, 2))
_Namespace_gml.addCategoryObject('elementBinding', TopoVolume.name().localName(), TopoVolume)

TopoComplex = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'TopoComplex'), TopoComplexType, documentation='gml:TopoComplex is a collection of topological primitives.\nEach complex holds a reference to its maximal complex (gml:maximalComplex) and optionally to sub- or super-complexes (gml:subComplex, gml:superComplex). \nA topology complex contains its primitive and sub-complex members.\n', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/topology.xsd', 334, 2))
_Namespace_gml.addCategoryObject('elementBinding', TopoComplex.name().localName(), TopoComplex)

subComplex = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'subComplex'), TopoComplexPropertyType, documentation='The property elements gml:subComplex, gml:superComplex and gml:maximalComplex provide an encoding for relationships between topology complexes as described for gml:TopoComplex above.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/topology.xsd', 342, 2))
_Namespace_gml.addCategoryObject('elementBinding', subComplex.name().localName(), subComplex)

superComplex = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'superComplex'), TopoComplexPropertyType, documentation='The property elements gml:subComplex, gml:superComplex and gml:maximalComplex provide an encoding for relationships between topology complexes as described for gml:TopoComplex above.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/topology.xsd', 347, 2))
_Namespace_gml.addCategoryObject('elementBinding', superComplex.name().localName(), superComplex)

maximalComplex = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'maximalComplex'), TopoComplexPropertyType, documentation='The property elements gml:subComplex, gml:superComplex and gml:maximalComplex provide an encoding for relationships between topology complexes as described for gml:TopoComplex above.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/topology.xsd', 352, 2))
_Namespace_gml.addCategoryObject('elementBinding', maximalComplex.name().localName(), maximalComplex)

topoPrimitiveMember = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'topoPrimitiveMember'), TopoPrimitiveMemberType, documentation='The gml:topoPrimitiveMember property element encodes for the relationship between a topology complex and a single topology primitive.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/topology.xsd', 357, 2))
_Namespace_gml.addCategoryObject('elementBinding', topoPrimitiveMember.name().localName(), topoPrimitiveMember)

unitOfMeasure = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'unitOfMeasure'), UnitOfMeasureType, documentation='The element gml:unitOfMeasure is a property element to refer to a unit of measure. This is an empty element which carries a reference to a unit of measure definition.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/units.xsd', 21, 1))
_Namespace_gml.addCategoryObject('elementBinding', unitOfMeasure.name().localName(), unitOfMeasure)

quantityType = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'quantityType'), StringOrRefType, documentation='The gml:quantityType property indicates the phenomenon to which the units apply. This element contains an informal description of the phenomenon or type of physical quantity that is measured or observed. When the physical quantity is the result of an observation or measurement, this term is known as observable type or measurand.\nThe use of gml:quantityType for references to remote values is deprecated.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/units.xsd', 48, 1))
_Namespace_gml.addCategoryObject('elementBinding', quantityType.name().localName(), quantityType)

quantityTypeReference = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'quantityTypeReference'), ReferenceType, documentation='The gml:quantityTypeReference property indicates the phenomenon to which the units apply. The content is a reference to a remote value.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/units.xsd', 54, 1))
_Namespace_gml.addCategoryObject('elementBinding', quantityTypeReference.name().localName(), quantityTypeReference)

Boolean_ = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'Boolean'), CTD_ANON_9, nillable=pyxb.binding.datatypes.boolean(1), location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/valueObjects.xsd', 24, 1))
_Namespace_gml.addCategoryObject('elementBinding', Boolean_.name().localName(), Boolean_)

BooleanList = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'BooleanList'), booleanOrNilReasonList, location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/valueObjects.xsd', 33, 1))
