AbstractDiscreteCoverage = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'AbstractDiscreteCoverage'), DiscreteCoverageType, abstract=pyxb.binding.datatypes.boolean(1), documentation='A discrete coverage consists of a domain set, range set and optionally a coverage function. The domain set consists of either spatial or temporal geometry objects, finite in number. The range set is comprised of a finite number of attribute values each of which is associated to every direct position within any single spatiotemporal object in the domain. In other words, the range values are constant on each spatiotemporal object in the domain. This coverage function maps each element from the coverage domain to an element in its range. The coverageFunction element describes the mapping function.\nThis element serves as the head of a substitution group which may contain any discrete coverage whose type is derived from gml:DiscreteCoverageType.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/coverage.xsd', 48, 1))
_Namespace_gml.addCategoryObject('elementBinding', AbstractDiscreteCoverage.name().localName(), AbstractDiscreteCoverage)

AbstractContinuousCoverage = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'AbstractContinuousCoverage'), AbstractContinuousCoverageType, abstract=pyxb.binding.datatypes.boolean(1), documentation='A continuous coverage as defined in ISO 19123 is a coverage that can return different values for the same feature attribute at different direct positions within a single spatiotemporal object in its spatiotemporal domain. The base type for continuous coverages is AbstractContinuousCoverageType.\nThe coverageFunction element describes the mapping function. \nThe abstract element gml:AbstractContinuousCoverage serves as the head of a substitution group which may contain any continuous coverage whose type is derived from gml:AbstractContinuousCoverageType.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/coverage.xsd', 63, 1))
_Namespace_gml.addCategoryObject('elementBinding', AbstractContinuousCoverage.name().localName(), AbstractContinuousCoverage)

MultiPointCoverage = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'MultiPointCoverage'), DiscreteCoverageType, documentation='In a gml:MultiPointCoverage the domain set is a gml:MultiPoint, that is a collection of arbitrarily distributed geometric points.\nThe content model is identical with gml:DiscreteCoverageType, but that gml:domainSet shall have values gml:MultiPoint.\nIn a gml:MultiPointCoverage the mapping from the domain to the range is straightforward.\n-\tFor gml:DataBlock encodings the points of the gml:MultiPoint are mapped in document order to the tuples of the data block.\n-\tFor gml:CompositeValue encodings the points of the gml:MultiPoint are mapped to the members of the composite value in document order.\n-\tFor gml:File encodings the points of the gml:MultiPoint are mapped to the records of the file in sequential order.\n', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/coverage.xsd', 236, 1))
_Namespace_gml.addCategoryObject('elementBinding', MultiPointCoverage.name().localName(), MultiPointCoverage)

MultiCurveCoverage = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'MultiCurveCoverage'), DiscreteCoverageType, documentation='In a gml:MultiCurveCoverage the domain is partioned into a collection of curves comprising a gml:MultiCurve.  The coverage function then maps each curve in the collection to a value in the range set.\nThe content model is identical with gml:DiscreteCoverageType, but that gml:domainSet shall have values gml:MultiCurve.\nIn a gml:MultiCurveCoverage the mapping from the domain to the range is straightforward.\n-\tFor gml:DataBlock encodings the curves of the gml:MultiCurve are mapped in document order to the tuples of the data block.\n-\tFor gml:CompositeValue encodings the curves of the gml:MultiCurve are mapped to the members of the composite value in document order.\n-\tFor gml:File encodings the curves of the gml:MultiCurve are mapped to the records of the file in sequential order.\n', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/coverage.xsd', 247, 1))
_Namespace_gml.addCategoryObject('elementBinding', MultiCurveCoverage.name().localName(), MultiCurveCoverage)

MultiSurfaceCoverage = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'MultiSurfaceCoverage'), DiscreteCoverageType, documentation='In a gml:MultiSurfaceCoverage the domain is partioned into a collection of surfaces comprising a gml:MultiSurface.  The coverage function than maps each surface in the collection to a value in the range set.\nThe content model is identical with gml:DiscreteCoverageType, but that gml:domainSet shall have values gml:MultiSurface.\nIn a gml:MultiSurfaceCoverage the mapping from the domain to the range is straightforward.\n-\tFor gml:DataBlock encodings the surfaces of the gml:MultiSurface are mapped in document order to the tuples of the data block.\n-\tFor gml:CompositeValue encodings the surfaces of the gml:MultiSurface are mapped to the members of the composite value in document order.\n-\tFor gml:File encodings the surfaces of the gml:MultiSurface are mapped to the records of the file in sequential order.\n', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/coverage.xsd', 258, 1))
_Namespace_gml.addCategoryObject('elementBinding', MultiSurfaceCoverage.name().localName(), MultiSurfaceCoverage)

MultiSolidCoverage = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'MultiSolidCoverage'), DiscreteCoverageType, documentation='In a gml:MultiSolidCoverage the domain is partioned into a collection of solids comprising a gml:MultiSolid.  The coverage function than maps each solid in the collection to a value in the range set.\nThe content model is identical with gml:DiscreteCoverageType, but that gml:domainSet shall have values gml:MultiSolid.\nIn a gml:MultiSolidCoverage the mapping from the domain to the range is straightforward.\n-\tFor gml:DataBlock encodings the solids of the gml:MultiSolid are mapped in document order to the tuples of the data block.\n-\tFor gml:CompositeValue encodings the solids of the gml:MultiSolid are mapped to the members of the composite value in document order.\n-\tFor gml:File encodings the solids of the gml:MultiSolid are mapped to the records of the file in sequential order.\n', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/coverage.xsd', 269, 1))
_Namespace_gml.addCategoryObject('elementBinding', MultiSolidCoverage.name().localName(), MultiSolidCoverage)

GridCoverage = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'GridCoverage'), DiscreteCoverageType, documentation='A gml:GriddedCoverage is a discrete point coverage in which the domain set is a geometric grid of points.\nNote that this is the same as the gml:MultiPointCoverage except that we have a gml:Grid to describe the domain.\nThe simple gridded coverage is not geometrically referenced and hence no geometric positions are assignable to the points in the grid. Such geometric positioning is introduced in the gml:RectifiedGridCoverage.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/coverage.xsd', 280, 1))
_Namespace_gml.addCategoryObject('elementBinding', GridCoverage.name().localName(), GridCoverage)

RectifiedGridCoverage = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'RectifiedGridCoverage'), DiscreteCoverageType, documentation='The gml:RectifiedGridCoverage is a discrete point coverage based on a rectified grid. It is similar to the grid coverage except that the points of the grid are geometrically referenced. The rectified grid coverage has a domain that is a gml:RectifiedGrid geometry.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/coverage.xsd', 287, 1))
_Namespace_gml.addCategoryObject('elementBinding', RectifiedGridCoverage.name().localName(), RectifiedGridCoverage)

greenwichLongitude = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'greenwichLongitude'), AngleType, documentation='gml:greenwichLongitude is the longitude of the prime meridian measured from the Greenwich meridian, positive eastward. If the value of the prime meridian "name" is "Greenwich" then the value of greenwichLongitude shall be 0 degrees.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/datums.xsd', 159, 1))
_Namespace_gml.addCategoryObject('elementBinding', greenwichLongitude.name().localName(), greenwichLongitude)

priorityLocation = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'priorityLocation'), PriorityLocationPropertyType, documentation='', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/deprecatedTypes.xsd', 790, 1))
_Namespace_gml.addCategoryObject('elementBinding', priorityLocation.name().localName(), priorityLocation)

FeatureCollection = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'FeatureCollection'), FeatureCollectionType, documentation='', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/deprecatedTypes.xsd', 860, 1))
_Namespace_gml.addCategoryObject('elementBinding', FeatureCollection.name().localName(), FeatureCollection)

DefinitionCollection = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'DefinitionCollection'), DictionaryType, documentation='', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/deprecatedTypes.xsd', 878, 1))
_Namespace_gml.addCategoryObject('elementBinding', DefinitionCollection.name().localName(), DefinitionCollection)

DefinitionProxy = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'DefinitionProxy'), DefinitionProxyType, documentation='', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/deprecatedTypes.xsd', 901, 1))
_Namespace_gml.addCategoryObject('elementBinding', DefinitionProxy.name().localName(), DefinitionProxy)

Dictionary = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'Dictionary'), DictionaryType, documentation='Sets of definitions may be collected into dictionaries or collections.\nA gml:Dictionary is a non-abstract collection of definitions.\nThe gml:Dictionary content model adds a list of gml:dictionaryEntry properties that contain or reference gml:Definition objects.  A database handle (gml:id attribute) is required, in order that this collection may be referred to. The standard gml:identifier, gml:description, gml:descriptionReference and gml:name properties are available to reference or contain more information about this dictionary. The gml:description and gml:descriptionReference property elements may be used for a description of this dictionary. The derived gml:name element may be used for the name(s) of this dictionary. for remote definiton references gml:dictionaryEntry shall be used. If a Definition object contained within a Dictionary uses the descriptionReference property to refer to a remote definition, then this enables the inclusion of a remote definition in a local dictionary, giving a handle and identifier in the context of the local dictionary.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/dictionary.xsd', 55, 1))
_Namespace_gml.addCategoryObject('elementBinding', Dictionary.name().localName(), Dictionary)

DynamicFeatureCollection = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'DynamicFeatureCollection'), DynamicFeatureCollectionType, documentation='A gml:DynamicFeatureCollection is a feature collection that has a gml:validTime property (i.e. is a snapshot of the feature collection) or which has a gml:history property that contains one or more gml:AbstractTimeSlices each of which contain values of the time varying properties of the feature collection.  Note that the gml:DynamicFeatureCollection may be one of the following:\n1.\tA feature collection which consists of static feature members (members do not change in time) but which has properties of the collection object as a whole that do change in time .  \n2.\tA feature collection which consists of dynamic feature members (the members are gml:DynamicFeatures) but which also has properties of the collection as a whole that vary in time.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/dynamicFeature.xsd', 51, 1))
_Namespace_gml.addCategoryObject('elementBinding', DynamicFeatureCollection.name().localName(), DynamicFeatureCollection)

MultiGeometry = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'MultiGeometry'), MultiGeometryType, documentation='gml:MultiGeometry is a collection of one or more GML geometry objects of arbitrary type. \nThe members of the geometric aggregate may be specified either using the "standard" property (gml:geometryMember) or the array property (gml:geometryMembers). It is also valid to use both the "standard" and the array properties in the same collection.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/geometryAggregates.xsd', 37, 1))
_Namespace_gml.addCategoryObject('elementBinding', MultiGeometry.name().localName(), MultiGeometry)

MultiPoint = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'MultiPoint'), MultiPointType, documentation='A gml:MultiPoint consists of one or more gml:Points.\nThe members of the geometric aggregate may be specified either using the "standard" property (gml:pointMember) or the array property (gml:pointMembers). It is also valid to use both the "standard" and the array properties in the same collection.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/geometryAggregates.xsd', 73, 1))
_Namespace_gml.addCategoryObject('elementBinding', MultiPoint.name().localName(), MultiPoint)

MultiCurve = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'MultiCurve'), MultiCurveType, documentation='A gml:MultiCurve is defined by one or more gml:AbstractCurves.\nThe members of the geometric aggregate may be specified either using the "standard" property (gml:curveMember) or the array property (gml:curveMembers). It is also valid to use both the "standard" and the array properties in the same collection.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/geometryAggregates.xsd', 109, 1))
_Namespace_gml.addCategoryObject('elementBinding', MultiCurve.name().localName(), MultiCurve)

MultiSurface = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'MultiSurface'), MultiSurfaceType, documentation='A gml:MultiSurface is defined by one or more gml:AbstractSurfaces.\nThe members of the geometric aggregate may be specified either using the "standard" property (gml:surfaceMember) or the array property (gml:surfaceMembers). It is also valid to use both the "standard" and the array properties in the same collection.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/geometryAggregates.xsd', 140, 1))
_Namespace_gml.addCategoryObject('elementBinding', MultiSurface.name().localName(), MultiSurface)

MultiSolid = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'MultiSolid'), MultiSolidType, documentation='A gml:MultiSolid is defined by one or more gml:AbstractSolids.\nThe members of the geometric aggregate may be specified either using the "standard" property (gml:solidMember) or the array property (gml:solidMembers). It is also valid to use both the "standard" and the array properties in the same collection.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/geometryAggregates.xsd', 171, 1))
_Namespace_gml.addCategoryObject('elementBinding', MultiSolid.name().localName(), MultiSolid)

Point = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'Point'), PointType, documentation='A Point is defined by a single coordinate tuple. The direct position of a point is specified by the pos element which is of type DirectPositionType.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/geometryBasic0d1d.xsd', 189, 1))
_Namespace_gml.addCategoryObject('elementBinding', Point.name().localName(), Point)

AbstractCurve = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'AbstractCurve'), AbstractCurveType, abstract=pyxb.binding.datatypes.boolean(1), documentation='The AbstractCurve element is the abstract head of the substitution group for all (continuous) curve elements.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/geometryBasic0d1d.xsd', 226, 1))
_Namespace_gml.addCategoryObject('elementBinding', AbstractCurve.name().localName(), AbstractCurve)

AbstractSurface = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'AbstractSurface'), AbstractSurfaceType, abstract=pyxb.binding.datatypes.boolean(1), documentation='The AbstractSurface element is the abstract head of the substitution group for all (continuous) surface elements.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/geometryBasic2d.xsd', 22, 1))
_Namespace_gml.addCategoryObject('elementBinding', AbstractSurface.name().localName(), AbstractSurface)

Circle = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'Circle'), CircleType, documentation='A Circle is an arc whose ends coincide to form a simple closed loop. The three control points shall be distinct non-co-linear points for the circle to be unambiguously defined. The arc is simply extended past the third control point until the first control point is encountered.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/geometryPrimitives.xsd', 173, 1))
_Namespace_gml.addCategoryObject('elementBinding', Circle.name().localName(), Circle)

Cone = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'Cone'), ConeType, location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/geometryPrimitives.xsd', 704, 1))
_Namespace_gml.addCategoryObject('elementBinding', Cone.name().localName(), Cone)

Cylinder = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'Cylinder'), CylinderType, location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/geometryPrimitives.xsd', 713, 1))
_Namespace_gml.addCategoryObject('elementBinding', Cylinder.name().localName(), Cylinder)

Sphere = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'Sphere'), SphereType, location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/geometryPrimitives.xsd', 722, 1))
_Namespace_gml.addCategoryObject('elementBinding', Sphere.name().localName(), Sphere)

AbstractSolid = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'AbstractSolid'), AbstractSolidType, abstract=pyxb.binding.datatypes.boolean(1), documentation='The AbstractSolid element is the abstract head of the substituition group for all (continuous) solid elements.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/geometryPrimitives.xsd', 775, 1))
_Namespace_gml.addCategoryObject('elementBinding', AbstractSolid.name().localName(), AbstractSolid)

RectifiedGrid = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'RectifiedGrid'), RectifiedGridType, documentation='A rectified grid is a grid for which there is an affine transformation between the grid coordinates and the coordinates of an external coordinate reference system. It is defined by specifying the position (in some geometric space) of the grid "origin" and of the vectors that specify the post locations.\nNote that the grid limits (post indexes) and axis name properties are inherited from gml:GridType and that gml:RectifiedGrid adds a gml:origin property (contains or references a gml:Point) and a set of gml:offsetVector properties.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/grids.xsd', 48, 1))
_Namespace_gml.addCategoryObject('elementBinding', RectifiedGrid.name().localName(), RectifiedGrid)

angle = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'angle'), AngleType, documentation='The gml:angle property element is used to record the value of an angle quantity as a single number, with its units.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/measures.xsd', 63, 1))
_Namespace_gml.addCategoryObject('elementBinding', angle.name().localName(), angle)

DirectedObservation = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'DirectedObservation'), DirectedObservationType, documentation='A gml:DirectedObservation is the same as an observation except that it adds an additional gml:direction property. This is the direction in which the observation was acquired. Clearly this applies only to certain types of observations such as visual observations by people, or observations obtained from terrestrial cameras.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/observation.xsd', 67, 1))
_Namespace_gml.addCategoryObject('elementBinding', DirectedObservation.name().localName(), DirectedObservation)

AbstractTimeGeometricPrimitive = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'AbstractTimeGeometricPrimitive'), AbstractTimeGeometricPrimitiveType, abstract=pyxb.binding.datatypes.boolean(1), documentation='gml:TimeGeometricPrimitive acts as the head of a substitution group for geometric temporal primitives.\nA temporal geometry shall be associated with a temporal reference system through the frame attribute that provides a URI reference that identifies a description of the reference system. Following ISO 19108, the Gregorian calendar with UTC is the default reference system, but others may also be used. The GPS calendar is an alternative reference systems in common use.\nThe two geometric primitives in the temporal dimension are the instant and the period. GML components are defined to support these as follows.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/temporal.xsd', 95, 1))
_Namespace_gml.addCategoryObject('elementBinding', AbstractTimeGeometricPrimitive.name().localName(), AbstractTimeGeometricPrimitive)

TimeReferenceSystem = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'TimeReferenceSystem'), TimeReferenceSystemType, documentation='A reference system is characterized in terms of its domain of validity: the spatial and temporal extent over which it is applicable. The basic GML element for temporal reference systems is gml:TimeReferenceSystem.  Its content model extends gml:DefinitionType with one additional property, gml:domainOfValidity.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/temporalReferenceSystems.xsd', 17, 1))
_Namespace_gml.addCategoryObject('elementBinding', TimeReferenceSystem.name().localName(), TimeReferenceSystem)

TimeCalendarEra = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'TimeCalendarEra'), TimeCalendarEraType, documentation='gml:TimeCalendarEra inherits basic properties from gml:DefinitionType and has the following additional properties:\n-\tgml:referenceEvent is the name or description of a mythical or historic event which fixes the position of the base scale of the calendar era.  This is given as text or using a link to description held elsewhere.\n-\tgml:referenceDate specifies the date of the referenceEvent expressed as a date in the given calendar.  In most calendars, this date is the origin (i.e., the first day) of the scale, but this is not always true.\n-\tgml:julianReference specifies the Julian date that corresponds to the reference date.  The Julian day number is an integer value; the Julian date is a decimal value that allows greater resolution.  Transforming calendar dates to and from Julian dates provides a relatively simple basis for transforming dates from one calendar to another.\n-\tgml:epochOfUse is the period for which the calendar era was used as a basis for dating.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/temporalReferenceSystems.xsd', 69, 1))
_Namespace_gml.addCategoryObject('elementBinding', TimeCalendarEra.name().localName(), TimeCalendarEra)

TimeOrdinalEra = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'TimeOrdinalEra'), TimeOrdinalEraType, documentation='Its content model follows the pattern of gml:TimeEdge, inheriting standard properties from gml:DefinitionType, and adding gml:start, gml:end and gml:extent properties, a set of gml:member properties which indicate ordered gml:TimeOrdinalEra elements, and a gml:group property which points to the parent era.\nThe recursive inclusion of gml:TimeOrdinalEra elements allow the construction of an arbitrary depth hierarchical ordinal reference schema, such that an ordinal era at a given level of the hierarchy includes a sequence of shorter, coterminous ordinal eras.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/temporalReferenceSystems.xsd', 159, 1))
_Namespace_gml.addCategoryObject('elementBinding', TimeOrdinalEra.name().localName(), TimeOrdinalEra)

AbstractTimeTopologyPrimitive = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'AbstractTimeTopologyPrimitive'), AbstractTimeTopologyPrimitiveType, abstract=pyxb.binding.datatypes.boolean(1), documentation='gml:TimeTopologyPrimitive acts as the head of a substitution group for topological temporal primitives.\nTemporal topology primitives shall imply the ordering information between features or feature properties. The temporal connection of features can be examined if they have temporal topology primitives as values of their properties. Usually, an instantaneous feature associates with a time node, and a static feature associates with a time edge.  A feature with both modes associates with the temporal topology primitive: a supertype of time nodes and time edges.\nA topological primitive is always connected to one or more other topological primitives, and is, therefore, always a member of a topological complex. In a GML instance, this will often be indicated by the primitives being described by elements that are descendents of an element describing a complex. However, in order to support the case where a temporal topological primitive is described in another context, the optional complex property is provided, which carries a reference to the parent temporal topological complex.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/temporalTopology.xsd', 15, 1))
_Namespace_gml.addCategoryObject('elementBinding', AbstractTimeTopologyPrimitive.name().localName(), AbstractTimeTopologyPrimitive)

TimeTopologyComplex = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'TimeTopologyComplex'), TimeTopologyComplexType, documentation='A temporal topology complex shall be the connected acyclic directed graph composed of temporal topological primitives, i.e. time nodes and time edges. Because a time edge may not exist without two time nodes on its boundaries, static features have time edges from a temporal topology complex as the values of their temporal properties, regardless of explicit declarations.\nA temporal topology complex expresses a linear or a non-linear graph. A temporal linear graph, composed of a sequence of time edges, provides a lineage described only by "substitution" of feature instances or feature element values. A time node as the start or the end of the graph connects with at least one time edge. A time node other than the start and the end shall connect to at least two time edges: one of starting from the node, and another ending at the node.\nA temporal topological complex is a set of connected temporal topological primitives. The member primtives are indicated, either by reference or by value, using the primitive property.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/temporalTopology.xsd', 41, 1))
_Namespace_gml.addCategoryObject('elementBinding', TimeTopologyComplex.name().localName(), TimeTopologyComplex)

Node = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'Node'), NodeType, documentation='gml:Node represents the 0-dimensional primitive.\nThe optional coboundary of a node (gml:directedEdge) is a sequence of directed edges which are incident on this node. Edges emanating from this node appear in the node coboundary with a negative orientation. \nIf provided, the aggregationType attribute shall have the value "sequence".\nA node may optionally be realised by a 0-dimensional geometric primitive (gml:pointProperty).', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/topology.xsd', 83, 2))
_Namespace_gml.addCategoryObject('elementBinding', Node.name().localName(), Node)

Edge = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'Edge'), EdgeType, documentation='gml:Edge represents the 1-dimensional primitive.\nThe topological boundary of an Edge (gml:directedNode) consists of a negatively directed start Node and a positively directed end Node.   \nThe optional coboundary of an edge (gml:directedFace) is a circular sequence of directed faces which are incident on this edge in document order. In the 2D case, the orientation of the face on the left of the edge is "+"; the orientation of the face on the right on its right is "-". \nIf provided, the aggregationType attribute shall have the value "sequence".\nAn edge may optionally be realised by a 1-dimensional geometric primitive (gml:curveProperty).', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/topology.xsd', 117, 2))
_Namespace_gml.addCategoryObject('elementBinding', Edge.name().localName(), Edge)

Face = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'Face'), FaceType, documentation='gml:Face represents the 2-dimensional topology primitive.\nThe topological boundary of a face (gml:directedEdge) consists of a sequence of directed edges. If provided, the aggregationType attribute shall have the value "sequence".\nThe optional coboundary of a face (gml:directedTopoSolid) is a pair of directed solids which are bounded by this face. A positively directed solid corresponds to a solid which lies in the direction of the negatively directed normal to the face in any geometric realisation. \nA face may optionally be realised by a 2-dimensional geometric primitive (gml:surfaceProperty).', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/topology.xsd', 157, 2))
_Namespace_gml.addCategoryObject('elementBinding', Face.name().localName(), Face)

TopoSolid = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'TopoSolid'), TopoSolidType, documentation='gml:TopoSolid represents the 3-dimensional topology primitive. \nThe topological boundary of a solid (gml:directedFace) consists of a set of directed faces.\nA solid may optionally be realised by a 3-dimensional geometric primitive (gml:solidProperty).', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/topology.xsd', 195, 2))
_Namespace_gml.addCategoryObject('elementBinding', TopoSolid.name().localName(), TopoSolid)

UnitDefinition = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'UnitDefinition'), UnitDefinitionType, documentation='A gml:UnitDefinition is a general definition of a unit of measure. This generic element is used only for units for which no relationship with other units or units systems is known.\nThe content model of gml:UnitDefinition adds three additional properties to gml:Definition, gml:quantityType, gml:quantityTypeReference and gml:catalogSymbol.  \nThe gml:catalogSymbol property optionally gives the short symbol used for this unit. This element is usually used when the relationship of this unit to other units or units systems is unknown.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/units.xsd', 30, 1))
_Namespace_gml.addCategoryObject('elementBinding', UnitDefinition.name().localName(), UnitDefinition)

derivationUnitTerm = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'derivationUnitTerm'), DerivationUnitTermType, documentation='A set of gml:derivationUnitTerm elements describes a derived unit of measure.  Each element carries an integer exponent.  The terms are combined by raising each referenced unit to the power of its exponent and forming the product.\nThis unit term references another unit of measure (uom) and provides an integer exponent applied to that unit in defining the compound unit. The exponent may be positive or negative, but not zero.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/units.xsd', 95, 1))
_Namespace_gml.addCategoryObject('elementBinding', derivationUnitTerm.name().localName(), derivationUnitTerm)

conversionToPreferredUnit = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'conversionToPreferredUnit'), ConversionToPreferredUnitType, documentation='The elements gml:conversionToPreferredUnit and gml:roughConversionToPreferredUnit represent parameters used to convert conventional units to preferred units for this physical quantity type.  A preferred unit is either a Base Unit or a Derived Unit that is selected for all values of one physical quantity type.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/units.xsd', 127, 1))
_Namespace_gml.addCategoryObject('elementBinding', conversionToPreferredUnit.name().localName(), conversionToPreferredUnit)

roughConversionToPreferredUnit = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'roughConversionToPreferredUnit'), ConversionToPreferredUnitType, documentation='The elements gml:conversionToPreferredUnit and gml:roughConversionToPreferredUnit represent parameters used to convert conventional units to preferred units for this physical quantity type.  A preferred unit is either a Base Unit or a Derived Unit that is selected for all values of one physical quantity type.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/units.xsd', 132, 1))
_Namespace_gml.addCategoryObject('elementBinding', roughConversionToPreferredUnit.name().localName(), roughConversionToPreferredUnit)

CategoryList = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'CategoryList'), CodeOrNilReasonListType, location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/valueObjects.xsd', 46, 1))
_Namespace_gml.addCategoryObject('elementBinding', CategoryList.name().localName(), CategoryList)

Quantity = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'Quantity'), CTD_ANON_12, nillable=pyxb.binding.datatypes.boolean(1), documentation='An XML attribute uom ("unit of measure") is required, whose value is a URI which identifies the definition of a ratio scale or units by which the numeric value shall be multiplied, or an interval or position scale on which the value occurs.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/valueObjects.xsd', 57, 1))
_Namespace_gml.addCategoryObject('elementBinding', Quantity.name().localName(), Quantity)

QuantityList = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'QuantityList'), MeasureOrNilReasonListType, location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/valueObjects.xsd', 69, 1))
_Namespace_gml.addCategoryObject('elementBinding', QuantityList.name().localName(), QuantityList)

CountExtent = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'CountExtent'), CountExtentType, location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/valueObjects.xsd', 167, 1))
_Namespace_gml.addCategoryObject('elementBinding', CountExtent.name().localName(), CountExtent)

AbstractCoordinateOperation = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'AbstractCoordinateOperation'), AbstractCoordinateOperationType, abstract=pyxb.binding.datatypes.boolean(1), documentation='gml:AbstractCoordinateOperation is a mathematical operation on coordinates that transforms or converts coordinates to another coordinate reference system. Many but not all coordinate operations (from CRS A to CRS B) also uniquely define the inverse operation (from CRS B to CRS A). In some cases, the operation method algorithm for the inverse operation is the same as for the forward algorithm, but the signs of some operation parameter values shall be reversed. In other cases, different algorithms are required for the forward and inverse operations, but the same operation parameter values are used. If (some) entirely different parameter values are needed, a different coordinate operation shall be defined.\nThe optional coordinateOperationAccuracy property elements provide estimates of the impact of this coordinate operation on point position accuracy.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/coordinateOperations.xsd', 23, 1))
_Namespace_gml.addCategoryObject('elementBinding', AbstractCoordinateOperation.name().localName(), AbstractCoordinateOperation)

AbstractSingleOperation = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'AbstractSingleOperation'), AbstractCoordinateOperationType, abstract=pyxb.binding.datatypes.boolean(1), documentation='gml:AbstractSingleOperation is a single (not concatenated) coordinate operation.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/coordinateOperations.xsd', 78, 1))
_Namespace_gml.addCategoryObject('elementBinding', AbstractSingleOperation.name().localName(), AbstractSingleOperation)

OperationMethod = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'OperationMethod'), OperationMethodType, documentation='gml:OperationMethod is a method (algorithm or procedure) used to perform a coordinate operation. Most operation methods use a number of operation parameters, although some coordinate conversions use none. Each coordinate operation using the method assigns values to these parameters.\nThe parameter elements are an unordered list of associations to the set of operation parameters and parameter groups used by this operation method.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/coordinateOperations.xsd', 385, 1))
_Namespace_gml.addCategoryObject('elementBinding', OperationMethod.name().localName(), OperationMethod)

AbstractGeneralOperationParameter = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'AbstractGeneralOperationParameter'), AbstractGeneralOperationParameterType, abstract=pyxb.binding.datatypes.boolean(1), documentation='gml:GeneralOperationParameter is the abstract definition of a parameter or group of parameters used by an operation method.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/coordinateOperations.xsd', 446, 1))
_Namespace_gml.addCategoryObject('elementBinding', AbstractGeneralOperationParameter.name().localName(), AbstractGeneralOperationParameter)

AbstractSingleCRS = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'AbstractSingleCRS'), AbstractCRSType, abstract=pyxb.binding.datatypes.boolean(1), documentation='gml:AbstractSingleCRS implements a coordinate reference system consisting of one coordinate system and one datum (as opposed to a Compound CRS).', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/coordinateReferenceSystems.xsd', 18, 1))
_Namespace_gml.addCategoryObject('elementBinding', AbstractSingleCRS.name().localName(), AbstractSingleCRS)

CoordinateSystemAxis = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'CoordinateSystemAxis'), CoordinateSystemAxisType, documentation='gml:CoordinateSystemAxis is a definition of a coordinate system axis.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/coordinateSystems.xsd', 19, 1))
_Namespace_gml.addCategoryObject('elementBinding', CoordinateSystemAxis.name().localName(), CoordinateSystemAxis)

AbstractCoordinateSystem = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'AbstractCoordinateSystem'), AbstractCoordinateSystemType, abstract=pyxb.binding.datatypes.boolean(1), documentation='gml:AbstractCoordinateSystem is a coordinate system (CS) is the non-repeating sequence of coordinate system axes that spans a given coordinate space. A CS is derived from a set of mathematical rules for specifying how coordinates in a given space are to be assigned to points. The coordinate values in a coordinate tuple shall be recorded in the order in which the coordinate system axes associations are recorded. This abstract complex type shall not be used, extended, or restricted, in an Application Schema, to define a concrete subtype with a meaning equivalent to a concrete subtype specified in this document.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/coordinateSystems.xsd', 78, 1))
_Namespace_gml.addCategoryObject('elementBinding', AbstractCoordinateSystem.name().localName(), AbstractCoordinateSystem)

AbstractDatum = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'AbstractDatum'), AbstractDatumType, abstract=pyxb.binding.datatypes.boolean(1), documentation='A gml:AbstractDatum specifies the relationship of a coordinate system to the earth, thus creating a coordinate reference system. A datum uses a parameter or set of parameters that determine the location of the origin of the coordinate reference system. Each datum subtype may be associated with only specific types of coordinate systems. This abstract complex type shall not be used, extended, or restricted, in a GML Application Schema, to define a concrete subtype with a meaning equivalent to a concrete subtype specified in this document.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/datums.xsd', 21, 1))
_Namespace_gml.addCategoryObject('elementBinding', AbstractDatum.name().localName(), AbstractDatum)

Ellipsoid = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'Ellipsoid'), EllipsoidType, documentation='A gml:Ellipsoid is a geometric figure that may be used to describe the approximate shape of the earth. In mathematical terms, it is a surface formed by the rotation of an ellipse about its minor axis.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/datums.xsd', 95, 1))
_Namespace_gml.addCategoryObject('elementBinding', Ellipsoid.name().localName(), Ellipsoid)

PrimeMeridian = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'PrimeMeridian'), PrimeMeridianType, documentation='A gml:PrimeMeridian defines the origin from which longitude values are determined. The default value for the prime meridian gml:identifier value is "Greenwich".', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/datums.xsd', 145, 1))
_Namespace_gml.addCategoryObject('elementBinding', PrimeMeridian.name().localName(), PrimeMeridian)

AbstractOperation = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'AbstractOperation'), AbstractCoordinateOperationType, abstract=pyxb.binding.datatypes.boolean(1), documentation='', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/deprecatedTypes.xsd', 83, 1))
_Namespace_gml.addCategoryObject('elementBinding', AbstractOperation.name().localName(), AbstractOperation)

LineString = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'LineString'), LineStringType, documentation='A LineString is a special curve that consists of a single segment with linear interpolation. It is defined by two or more coordinate tuples, with linear interpolation between them. The number of direct positions in the list shall be at least two.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/geometryBasic0d1d.xsd', 272, 1))
_Namespace_gml.addCategoryObject('elementBinding', LineString.name().localName(), LineString)

Polygon = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'Polygon'), PolygonType, documentation='A Polygon is a special surface that is defined by a single surface patch (see D.3.6). The boundary of this patch is coplanar and the polygon uses planar interpolation in its interior. \nThe elements exterior and interior describe the surface boundary of the polygon.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/geometryBasic2d.xsd', 61, 1))
_Namespace_gml.addCategoryObject('elementBinding', Polygon.name().localName(), Polygon)

AbstractRing = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'AbstractRing'), AbstractRingType, abstract=pyxb.binding.datatypes.boolean(1), documentation='An abstraction of a ring to support surface boundaries of different complexity.\nThe AbstractRing element is the abstract head of the substituition group for all closed boundaries of a surface patch.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/geometryBasic2d.xsd', 84, 1))
_Namespace_gml.addCategoryObject('elementBinding', AbstractRing.name().localName(), AbstractRing)

CompositeCurve = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'CompositeCurve'), CompositeCurveType, documentation='A gml:CompositeCurve is represented by a sequence of (orientable) curves such that each curve in the sequence terminates at the start point of the subsequent curve in the list. \ncurveMember references or contains inline one curve in the composite curve. \nThe curves are contiguous, the collection of curves is ordered. Therefore, if provided, the aggregationType attribute shall have the value "sequence".', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/geometryComplexes.xsd', 54, 1))
_Namespace_gml.addCategoryObject('elementBinding', CompositeCurve.name().localName(), CompositeCurve)

CompositeSurface = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'CompositeSurface'), CompositeSurfaceType, documentation='A gml:CompositeSurface is represented by a set of orientable surfaces. It is geometry type with all the geometric properties of a (primitive) surface. Essentially, a composite surface is a collection of surfaces that join in pairs on common boundary curves and which, when considered as a whole, form a single surface.\nsurfaceMember references or contains inline one surface in the composite surface. \nThe surfaces are contiguous.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/geometryComplexes.xsd', 71, 1))
_Namespace_gml.addCategoryObject('elementBinding', CompositeSurface.name().localName(), CompositeSurface)

CompositeSolid = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'CompositeSolid'), CompositeSolidType, documentation='gml:CompositeSolid implements ISO 19107 GM_CompositeSolid (see ISO 19107:2003, 6.6.7) as specified in D.2.3.6. \nA gml:CompositeSolid is represented by a set of orientable surfaces. It is a geometry type with all the geometric properties of a (primitive) solid. Essentially, a composite solid is a collection of solids that join in pairs on common boundary surfaces and which, when considered as a whole, form a single solid. \nsolidMember references or contains one solid in the composite solid. The solids are contiguous.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/geometryComplexes.xsd', 88, 1))
_Namespace_gml.addCategoryObject('elementBinding', CompositeSolid.name().localName(), CompositeSolid)

Curve = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'Curve'), CurveType, documentation='A curve is a 1-dimensional primitive. Curves are continuous, connected, and have a measurable length in terms of the coordinate system. \nA curve is composed of one or more curve segments. Each curve segment within a curve may be defined using a different interpolation method. The curve segments are connected to one another, with the end point of each segment except the last being the start point of the next segment in the segment list.\nThe orientation of the curve is positive.\nThe element segments encapsulates the segments of the curve.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/geometryPrimitives.xsd', 24, 1))
_Namespace_gml.addCategoryObject('elementBinding', Curve.name().localName(), Curve)

OrientableCurve = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'OrientableCurve'), OrientableCurveType, documentation='OrientableCurve consists of a curve and an orientation. If the orientation is "+", then the OrientableCurve is identical to the baseCurve. If the orientation is "-", then the OrientableCurve is related to another AbstractCurve with a parameterization that reverses the sense of the curve traversal.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/geometryPrimitives.xsd', 47, 1))
_Namespace_gml.addCategoryObject('elementBinding', OrientableCurve.name().localName(), OrientableCurve)

Surface = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'Surface'), SurfaceType, documentation='A Surface is a 2-dimensional primitive and is composed of one or more surface patches as specified in ISO 19107:2003, 6.3.17.1. The surface patches are connected to one another.\npatches encapsulates the patches of the surface.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/geometryPrimitives.xsd', 507, 1))
_Namespace_gml.addCategoryObject('elementBinding', Surface.name().localName(), Surface)

OrientableSurface = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'OrientableSurface'), OrientableSurfaceType, documentation='OrientableSurface consists of a surface and an orientation. If the orientation is "+", then the OrientableSurface is identical to the baseSurface. If the orientation is "-", then the OrientableSurface is a reference to a gml:AbstractSurface with an up-normal that reverses the direction for this OrientableSurface, the sense of "the top of the surface".', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/geometryPrimitives.xsd', 528, 1))
_Namespace_gml.addCategoryObject('elementBinding', OrientableSurface.name().localName(), OrientableSurface)

PolyhedralSurface = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'PolyhedralSurface'), SurfaceType, documentation='A polyhedral surface is a surface composed of polygon patches connected along their common boundary curves. This differs from the surface type only in the restriction on the types of surface patches acceptable.\npolygonPatches encapsulates the polygon patches of the polyhedral surface.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/geometryPrimitives.xsd', 723, 1))
_Namespace_gml.addCategoryObject('elementBinding', PolyhedralSurface.name().localName(), PolyhedralSurface)

TriangulatedSurface = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'TriangulatedSurface'), SurfaceType, documentation='A triangulated surface is a polyhedral surface that is composed only of triangles. There is no restriction on how the triangulation is derived.\ntrianglePatches encapsulates the triangles of the triangulated surface.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/geometryPrimitives.xsd', 729, 1))
_Namespace_gml.addCategoryObject('elementBinding', TriangulatedSurface.name().localName(), TriangulatedSurface)

Solid = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'Solid'), SolidType, documentation='A solid is the basis for 3-dimensional geometry. The extent of a solid is defined by the boundary surfaces as specified in ISO 19107:2003, 6.3.18. exterior specifies the outer boundary, interior the inner boundary of the solid.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/geometryPrimitives.xsd', 814, 1))
_Namespace_gml.addCategoryObject('elementBinding', Solid.name().localName(), Solid)

Shell = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'Shell'), ShellType, documentation='A shell is used to represent a single connected component of a solid boundary as specified in ISO 19107:2003, 6.3.8.\nEvery gml:surfaceMember references or contains one surface, i.e. any element which is substitutable for gml:AbstractSurface. In the context of a shell, the surfaces describe the boundary of the solid. \nIf provided, the aggregationType attribute shall have the value "set".\n', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/geometryPrimitives.xsd', 829, 1))
_Namespace_gml.addCategoryObject('elementBinding', Shell.name().localName(), Shell)

DirectedObservationAtDistance = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'DirectedObservationAtDistance'), DirectedObservationAtDistanceType, documentation='gml:DirectedObservationAtDistance adds an additional distance property. This is the distance from the observer to the subject of the observation. Clearly this applies only to certain types of observations such as visual observations by people, or observations obtained from terrestrial cameras.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/observation.xsd', 81, 1))
_Namespace_gml.addCategoryObject('elementBinding', DirectedObservationAtDistance.name().localName(), DirectedObservationAtDistance)

AbstractCRS = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'AbstractCRS'), AbstractCRSType, abstract=pyxb.binding.datatypes.boolean(1), documentation='gml:AbstractCRS specifies a coordinate reference system which is usually single but may be compound. This abstract complex type shall not be used, extended, or restricted, in a GML Application Schema, to define a concrete subtype with a meaning equivalent to a concrete subtype specified in this document.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/referenceSystems.xsd', 30, 1))
_Namespace_gml.addCategoryObject('elementBinding', AbstractCRS.name().localName(), AbstractCRS)

TimeInstant = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'TimeInstant'), TimeInstantType, documentation='gml:TimeInstant acts as a zero-dimensional geometric primitive that represents an identifiable position in time.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/temporal.xsd', 109, 1))
_Namespace_gml.addCategoryObject('elementBinding', TimeInstant.name().localName(), TimeInstant)

TimePeriod = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'TimePeriod'), TimePeriodType, documentation='gml:TimePeriod acts as a one-dimensional geometric primitive that represents an identifiable extent in time.\nThe location in of a gml:TimePeriod is described by the temporal positions of the instants at which it begins and ends. The length of the period is equal to the temporal distance between the two bounding temporal positions. \nBoth beginning and end may be described in terms of their direct position using gml:TimePositionType which is an XML Schema simple content type, or by reference to an indentifiable time instant using gml:TimeInstantPropertyType.\nAlternatively a limit of a gml:TimePeriod may use the conventional GML property model to make a reference to a time instant described elsewhere, or a limit may be indicated as a direct position.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/temporal.xsd', 133, 1))
_Namespace_gml.addCategoryObject('elementBinding', TimePeriod.name().localName(), TimePeriod)

TimeCoordinateSystem = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'TimeCoordinateSystem'), TimeCoordinateSystemType, documentation='A temporal coordinate system shall be based on a continuous interval scale defined in terms of a single time interval.\nThe differences to ISO 19108 TM_CoordinateSystem are:\n-\tthe origin is specified either using the property gml:originPosition whose value is a direct time position, or using the property gml:origin whose model is gml:TimeInstantPropertyType; this permits more flexibility in representation and also supports referring to a value fixed elsewhere;\n-\tthe interval uses gml:TimeIntervalLengthType.\n', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/temporalReferenceSystems.xsd', 31, 1))
_Namespace_gml.addCategoryObject('elementBinding', TimeCoordinateSystem.name().localName(), TimeCoordinateSystem)

TimeCalendar = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'TimeCalendar'), TimeCalendarType, documentation='A calendar is a discrete temporal reference system that provides a basis for defining temporal position to a resolution of one day.\ngml:TimeCalendar adds one property to those inherited from gml:TimeReferenceSystem. A gml:referenceFrame provides a link to a gml:TimeCalendarEra that it uses. A  gml:TimeCalendar may reference more than one calendar era. \nThe referenceFrame element follows the standard GML property model, allowing the association to be instantiated either using an inline description using the gml:TimeCalendarEra element, or a link to a gml:TimeCalendarEra which is explicit elsewhere.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/temporalReferenceSystems.xsd', 53, 1))
_Namespace_gml.addCategoryObject('elementBinding', TimeCalendar.name().localName(), TimeCalendar)

TimeClock = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'TimeClock'), TimeClockType, documentation='A clock provides a basis for defining temporal position within a day. A clock shall be used with a calendar in order to provide a complete description of a temporal position within a specific day.\ngml:TimeClock adds the following properties to those inherited from gml:TimeReferenceSystemType:\n-\tgml:referenceEvent is the name or description of an event, such as solar noon or sunrise, which fixes the position of the base scale of the clock.\n-\tgml:referenceTime specifies the time of day associated with the reference event expressed as a time of day in the given clock. The reference time is usually the origin of the clock scale. \n-\tgml:utcReference specifies the 24 hour local or UTC time that corresponds to the reference time.\n-\tgml:dateBasis contains or references the calendars that use this clock.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/temporalReferenceSystems.xsd', 110, 1))
_Namespace_gml.addCategoryObject('elementBinding', TimeClock.name().localName(), TimeClock)

TimeOrdinalReferenceSystem = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'TimeOrdinalReferenceSystem'), TimeOrdinalReferenceSystemType, documentation='In some applications of geographic information — such as geology and archaeology — relative position in time is known more precisely than absolute time or duration. The order of events in time can be well established, but the magnitude of the intervals between them cannot be accurately determined; in such cases, the use of an ordinal temporal reference system is appropriate. An ordinal temporal reference system is composed of a sequence of named coterminous eras, which may in turn be composed of sequences of member eras at a finer scale, giving the whole a hierarchical structure of eras of verying resolution. \nAn ordinal temporal reference system whose component eras are not further subdivided is effectively a temporal topological complex constrained to be a linear graph. An ordinal temporal reference system some or all of whose component eras are subdivided is effectively a temporal topological complex with the constraint that parallel branches may only be constructed in pairs where one is a single temporal ordinal era and the other is a sequence of temporal ordinal eras that are called "members" of the "group". This constraint means that within a single temporal ordinal reference system, the relative position of all temporal ordinal eras is unambiguous.  \nThe positions of the beginning and end of a given era may calibrate the relative time scale.\ngml:TimeOrdinalReferenceSystem adds one or more gml:component properties to the generic temporal reference system model.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/temporalReferenceSystems.xsd', 142, 1))
_Namespace_gml.addCategoryObject('elementBinding', TimeOrdinalReferenceSystem.name().localName(), TimeOrdinalReferenceSystem)

TimeNode = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'TimeNode'), TimeNodeType, documentation='A time node is a zero-dimensional topological primitive that represents an identifiable node in time (it is equivalent to a point in space). A node may act as the termination or initiation of any number of time edges. A time node may be realised as a geometry, its position, whose value is a time instant.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/temporalTopology.xsd', 67, 1))
_Namespace_gml.addCategoryObject('elementBinding', TimeNode.name().localName(), TimeNode)

TimeEdge = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'TimeEdge'), TimeEdgeType, documentation='A time edge is a one-dimensional topological primitive. It is an open interval that starts and ends at a node. The edge may be realised as a geometry whose value is a time period.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/temporalTopology.xsd', 93, 1))
_Namespace_gml.addCategoryObject('elementBinding', TimeEdge.name().localName(), TimeEdge)

BaseUnit = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'BaseUnit'), BaseUnitType, documentation='A base unit is a unit of measure that cannot be derived by combination of other base units within a particular system of units.  For example, in the SI system of units, the base units are metre, kilogram, second, Ampere, Kelvin, mole, and candela, for the physical quantity types length, mass, time interval, electric current, thermodynamic temperature, amount of substance and luminous intensity, respectively.\ngml:BaseUnit extends generic gml:UnitDefinition with the property gml:unitsSystem, which carries a reference to the units system to which this base unit is asserted to belong.  ', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/units.xsd', 65, 1))
_Namespace_gml.addCategoryObject('elementBinding', BaseUnit.name().localName(), BaseUnit)

DerivedUnit = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'DerivedUnit'), DerivedUnitType, documentation='Derived units are defined by combination of other units.  Derived units are used for quantities other than those corresponding to the base units, such as hertz (s-1) for frequency, Newton (kg.m/s2) for force.  Derived units based directly on base units are usually preferred for quantities other than the fundamental quantities within a system. If a derived unit is not the preferred unit, the gml:ConventionalUnit element should be used instead.\nThe gml:DerivedUnit extends gml:UnitDefinition with the property gml:derivationUnitTerms.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/units.xsd', 80, 1))
_Namespace_gml.addCategoryObject('elementBinding', DerivedUnit.name().localName(), DerivedUnit)

ConventionalUnit = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'ConventionalUnit'), ConventionalUnitType, documentation='Conventional units that are neither base units nor defined by direct combination of base units are used in many application domains.  For example electronVolt for energy, feet and nautical miles for length.  In most cases there is a known, usually linear, conversion to a preferred unit which is either a base unit or derived by direct combination of base units.\nThe gml:ConventionalUnit extends gml:UnitDefinition with a property that describes a conversion to a preferred unit for this physical quantity.  When the conversion is exact, the element gml:conversionToPreferredUnit should be used, or when the conversion is not exact the element gml:roughConversionToPreferredUnit is available. Both of these elements have the same content model.  The gml:derivationUnitTerm property defined above is included to allow a user to optionally record how this unit may be derived from other ("more primitive") units.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/units.xsd', 108, 1))
_Namespace_gml.addCategoryObject('elementBinding', ConventionalUnit.name().localName(), ConventionalUnit)

CategoryExtent = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'CategoryExtent'), CategoryExtentType, location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/valueObjects.xsd', 159, 1))
_Namespace_gml.addCategoryObject('elementBinding', CategoryExtent.name().localName(), CategoryExtent)

QuantityExtent = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'QuantityExtent'), QuantityExtentType, location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/valueObjects.xsd', 173, 1))
_Namespace_gml.addCategoryObject('elementBinding', QuantityExtent.name().localName(), QuantityExtent)

AbstractGeneralConversion = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'AbstractGeneralConversion'), AbstractGeneralConversionType, abstract=pyxb.binding.datatypes.boolean(1), documentation='gm:AbstractGeneralConversion is an abstract operation on coordinates that does not include any change of datum. The best-known example of a coordinate conversion is a map projection. The parameters describing coordinate conversions are defined rather than empirically derived. Note that some conversions have no parameters. The operationVersion, sourceCRS, and targetCRS elements are omitted in a coordinate conversion.\nThis abstract complex type is expected to be extended for well-known operation methods with many Conversion instances, in GML Application Schemas that define operation-method-specialized element names and contents. This conversion uses an operation method, usually with associated parameter values. However, operation methods and parameter values are directly associated with concrete subtypes, not with this abstract type. All concrete types derived from this type shall extend this type to include a "usesMethod" element that references the "OperationMethod" element. Similarly, all concrete types derived from this type shall extend this type to include zero or more elements each named "uses...Value" that each use the type of an element substitutable for the "AbstractGeneralParameterValue" element.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/coordinateOperations.xsd', 92, 1))
_Namespace_gml.addCategoryObject('elementBinding', AbstractGeneralConversion.name().localName(), AbstractGeneralConversion)

AbstractGeneralTransformation = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'AbstractGeneralTransformation'), AbstractGeneralTransformationType, abstract=pyxb.binding.datatypes.boolean(1), documentation='gml:AbstractGeneralTransformation is an abstract operation on coordinates that usually includes a change of Datum. The parameters of a coordinate transformation are empirically derived from data containing the coordinates of a series of points in both coordinate reference systems. This computational process is usually "over-determined", allowing derivation of error (or accuracy) estimates for the transformation. Also, the stochastic nature of the parameters may result in multiple (different) versions of the same coordinate transformation. The operationVersion, sourceCRS, and targetCRS proeprty elements are mandatory in a coordinate transformation.\nThis abstract complex type is expected to be extended for well-known operation methods with many Transformation instances, in Application Schemas that define operation-method-specialized value element names and contents. This transformation uses an operation method with associated parameter values. However, operation methods and parameter values are directly associated with concrete subtypes, not with this abstract type. All concrete types derived from this type shall extend this type to include a "usesMethod" element that references one "OperationMethod" element. Similarly, all concrete types derived from this type shall extend this type to include one or more elements each named "uses...Value" that each use the type of an element substitutable for the "AbstractGeneralParameterValue" element.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/coordinateOperations.xsd', 125, 1))
_Namespace_gml.addCategoryObject('elementBinding', AbstractGeneralTransformation.name().localName(), AbstractGeneralTransformation)

ConcatenatedOperation = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'ConcatenatedOperation'), ConcatenatedOperationType, location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/coordinateOperations.xsd', 161, 1))
_Namespace_gml.addCategoryObject('elementBinding', ConcatenatedOperation.name().localName(), ConcatenatedOperation)

PassThroughOperation = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'PassThroughOperation'), PassThroughOperationType, documentation='gml:PassThroughOperation is a pass-through operation specifies that a subset of a coordinate tuple is subject to a specific coordinate operation.\nThe modifiedCoordinate property elements are an ordered sequence of positive integers defining the positions in a coordinate tuple of the coordinates affected by this pass-through operation. The AggregationAttributeGroup should be used to specify that the modifiedCoordinate elements are ordered.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/coordinateOperations.xsd', 190, 1))
_Namespace_gml.addCategoryObject('elementBinding', PassThroughOperation.name().localName(), PassThroughOperation)

OperationParameter = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'OperationParameter'), OperationParameterType, documentation='gml:OperationParameter is the definition of a parameter used by an operation method. Most parameter values are numeric, but other types of parameter values are possible. This complex type is expected to be used or extended for all operation methods, without defining operation-method-specialized element names.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/coordinateOperations.xsd', 474, 1))
_Namespace_gml.addCategoryObject('elementBinding', OperationParameter.name().localName(), OperationParameter)

OperationParameterGroup = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'OperationParameterGroup'), OperationParameterGroupType, documentation='gml:OperationParameterGroup is the definition of a group of parameters used by an operation method. This complex type is expected to be used or extended for all applicable operation methods, without defining operation-method-specialized element names.\nThe generalOperationParameter elements are an unordered list of associations to the set of operation parameters that are members of this group.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/coordinateOperations.xsd', 495, 1))
_Namespace_gml.addCategoryObject('elementBinding', OperationParameterGroup.name().localName(), OperationParameterGroup)

AbstractGeneralDerivedCRS = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'AbstractGeneralDerivedCRS'), AbstractGeneralDerivedCRSType, abstract=pyxb.binding.datatypes.boolean(1), documentation='gml:AbstractGeneralDerivedCRS is a coordinate reference system that is defined by its coordinate conversion from another coordinate reference system. This abstract complex type shall not be used, extended, or restricted, in a GML Application Schema, to define a concrete subtype with a meaning equivalent to a concrete subtype specified in this document.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/coordinateReferenceSystems.xsd', 32, 1))
_Namespace_gml.addCategoryObject('elementBinding', AbstractGeneralDerivedCRS.name().localName(), AbstractGeneralDerivedCRS)

CompoundCRS = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'CompoundCRS'), CompoundCRSType, documentation='gml:CompundCRS is a coordinate reference system describing the position of points through two or more independent coordinate reference systems. It is associated with a non-repeating sequence of two or more instances of SingleCRS.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/coordinateReferenceSystems.xsd', 51, 1))
_Namespace_gml.addCategoryObject('elementBinding', CompoundCRS.name().localName(), CompoundCRS)

GeodeticCRS = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'GeodeticCRS'), GeodeticCRSType, location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/coordinateReferenceSystems.xsd', 80, 1))
_Namespace_gml.addCategoryObject('elementBinding', GeodeticCRS.name().localName(), GeodeticCRS)

VerticalCRS = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'VerticalCRS'), VerticalCRSType, documentation='gml:VerticalCRS is a 1D coordinate reference system used for recording heights or depths. Vertical CRSs make use of the direction of gravity to define the concept of height or depth, but the relationship with gravity may not be straightforward. By implication, ellipsoidal heights (h) cannot be captured in a vertical coordinate reference system. Ellipsoidal heights cannot exist independently, but only as an inseparable part of a 3D coordinate tuple defined in a geographic 3D coordinate reference system.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/coordinateReferenceSystems.xsd', 128, 1))
_Namespace_gml.addCategoryObject('elementBinding', VerticalCRS.name().localName(), VerticalCRS)

EngineeringCRS = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'EngineeringCRS'), EngineeringCRSType, documentation='gml:EngineeringCRS is a contextually local coordinate reference system which can be divided into two broad categories:\n-\tearth-fixed systems applied to engineering activities on or near the surface of the earth;\n-\tCRSs on moving platforms such as road vehicles, vessels, aircraft, or spacecraft, see ISO 19111 8.3.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/coordinateReferenceSystems.xsd', 234, 1))
_Namespace_gml.addCategoryObject('elementBinding', EngineeringCRS.name().localName(), EngineeringCRS)

ImageCRS = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'ImageCRS'), ImageCRSType, documentation='gml:ImageCRS is an engineering coordinate reference system applied to locations in images. Image coordinate reference systems are treated as a separate sub-type because the definition of the associated image datum contains two attributes not relevant to other engineering datums.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/coordinateReferenceSystems.xsd', 298, 1))
_Namespace_gml.addCategoryObject('elementBinding', ImageCRS.name().localName(), ImageCRS)

TemporalCRS = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'TemporalCRS'), TemporalCRSType, documentation='gml:TemporalCRS is a 1D coordinate reference system used for the recording of time.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/coordinateReferenceSystems.xsd', 336, 1))
_Namespace_gml.addCategoryObject('elementBinding', TemporalCRS.name().localName(), TemporalCRS)

EllipsoidalCS = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'EllipsoidalCS'), EllipsoidalCSType, documentation='gml:EllipsoidalCS is a two- or three-dimensional coordinate system in which position is specified by geodetic latitude, geodetic longitude, and (in the three-dimensional case) ellipsoidal height. An EllipsoidalCS shall have two or three gml:axis property elements; the number of associations shall equal the dimension of the CS.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/coordinateSystems.xsd', 107, 1))
_Namespace_gml.addCategoryObject('elementBinding', EllipsoidalCS.name().localName(), EllipsoidalCS)

CartesianCS = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'CartesianCS'), CartesianCSType, documentation='gml:CartesianCS is a 1-, 2-, or 3-dimensional coordinate system. In the 1-dimensional case, it contains a single straight coordinate axis. In the 2- and 3-dimensional cases gives the position of points relative to orthogonal straight axes. In the multi-dimensional case, all axes shall have the same length unit of measure. A CartesianCS shall have one, two, or three gml:axis property elements.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/coordinateSystems.xsd', 126, 1))
_Namespace_gml.addCategoryObject('elementBinding', CartesianCS.name().localName(), CartesianCS)

VerticalCS = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'VerticalCS'), VerticalCSType, documentation="gml:VerticalCS is a one-dimensional coordinate system used to record the heights or depths of points. Such a coordinate system is usually dependent on the Earth's gravity field, perhaps loosely as when atmospheric pressure is the basis for the vertical coordinate system axis. A VerticalCS shall have one gml:axis property element.", location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/coordinateSystems.xsd', 145, 1))
_Namespace_gml.addCategoryObject('elementBinding', VerticalCS.name().localName(), VerticalCS)

TimeCS = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'TimeCS'), TimeCSType, documentation='gml:TimeCS is a one-dimensional coordinate system containing a time axis, used to describe the temporal position of a point in the specified time units from a specified time origin. A TimeCS shall have one gml:axis property element.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/coordinateSystems.xsd', 164, 1))
_Namespace_gml.addCategoryObject('elementBinding', TimeCS.name().localName(), TimeCS)

LinearCS = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'LinearCS'), LinearCSType, documentation='gml:LinearCS is a one-dimensional coordinate system that consists of the points that lie on the single axis described. The associated coordinate is the distance – with or without offset – from the specified datum to the point along the axis. A LinearCS shall have one gml:axis property element.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/coordinateSystems.xsd', 183, 1))
_Namespace_gml.addCategoryObject('elementBinding', LinearCS.name().localName(), LinearCS)

UserDefinedCS = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'UserDefinedCS'), UserDefinedCSType, documentation='gml:UserDefinedCS is a two- or three-dimensional coordinate system that consists of any combination of coordinate axes not covered by any other coordinate system type. A UserDefinedCS shall have two or three gml:axis property elements; the number of property elements shall equal the dimension of the CS.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/coordinateSystems.xsd', 202, 1))
_Namespace_gml.addCategoryObject('elementBinding', UserDefinedCS.name().localName(), UserDefinedCS)

SphericalCS = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'SphericalCS'), SphericalCSType, documentation='gml:SphericalCS is a three-dimensional coordinate system with one distance measured from the origin and two angular coordinates. A SphericalCS shall have three gml:axis property elements.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/coordinateSystems.xsd', 221, 1))
_Namespace_gml.addCategoryObject('elementBinding', SphericalCS.name().localName(), SphericalCS)

PolarCS = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'PolarCS'), PolarCSType, documentation='gml:PolarCS ia s two-dimensional coordinate system in which position is specified by the distance from the origin and the angle between the line from the origin to a point and a reference direction. A PolarCS shall have two gml:axis property elements.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/coordinateSystems.xsd', 240, 1))
_Namespace_gml.addCategoryObject('elementBinding', PolarCS.name().localName(), PolarCS)

CylindricalCS = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'CylindricalCS'), CylindricalCSType, documentation='gml:CylindricalCS is a three-dimensional coordinate system consisting of a polar coordinate system extended by a straight coordinate axis perpendicular to the plane spanned by the polar coordinate system. A CylindricalCS shall have three gml:axis property elements.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/coordinateSystems.xsd', 259, 1))
_Namespace_gml.addCategoryObject('elementBinding', CylindricalCS.name().localName(), CylindricalCS)

AffineCS = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'AffineCS'), AffineCSType, documentation='gml:AffineCS is a two- or three-dimensional coordinate system with straight axes that are not necessarily orthogonal. An AffineCS shall have two or three gml:axis property elements; the number of property elements shall equal the dimension of the CS.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/coordinateSystems.xsd', 278, 1))
_Namespace_gml.addCategoryObject('elementBinding', AffineCS.name().localName(), AffineCS)

GeodeticDatum = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'GeodeticDatum'), GeodeticDatumType, documentation='gml:GeodeticDatum is a geodetic datum defines the precise location and orientation in 3-dimensional space of a defined ellipsoid (or sphere), or of a Cartesian coordinate system centered in this ellipsoid (or sphere).', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/datums.xsd', 61, 1))
_Namespace_gml.addCategoryObject('elementBinding', GeodeticDatum.name().localName(), GeodeticDatum)

EngineeringDatum = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'EngineeringDatum'), EngineeringDatumType, documentation='gml:EngineeringDatum defines the origin of an engineering coordinate reference system, and is used in a region around that origin. This origin may be fixed with respect to the earth (such as a defined point at a construction site), or be a defined point on a moving vehicle (such as on a ship or satellite).', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/datums.xsd', 173, 1))
_Namespace_gml.addCategoryObject('elementBinding', EngineeringDatum.name().localName(), EngineeringDatum)

ImageDatum = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'ImageDatum'), ImageDatumType, documentation='gml:ImageDatum defines the origin of an image coordinate reference system, and is used in a local context only. For an image datum, the anchor definition is usually either the centre of the image or the corner of the image. For more information, see ISO 19111 B.3.5.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/datums.xsd', 192, 1))
_Namespace_gml.addCategoryObject('elementBinding', ImageDatum.name().localName(), ImageDatum)

VerticalDatum = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'VerticalDatum'), VerticalDatumType, documentation='gml:VerticalDatum is a textual description and/or a set of parameters identifying a particular reference level surface used as a zero-height surface, including its position with respect to the Earth for any of the height types recognized by this International Standard.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/datums.xsd', 220, 1))
_Namespace_gml.addCategoryObject('elementBinding', VerticalDatum.name().localName(), VerticalDatum)

TemporalCS = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'TemporalCS'), TemporalCSType, documentation='', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/deprecatedTypes.xsd', 247, 1))
_Namespace_gml.addCategoryObject('elementBinding', TemporalCS.name().localName(), TemporalCS)

ObliqueCartesianCS = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'ObliqueCartesianCS'), ObliqueCartesianCSType, documentation='', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/deprecatedTypes.xsd', 299, 1))
_Namespace_gml.addCategoryObject('elementBinding', ObliqueCartesianCS.name().localName(), ObliqueCartesianCS)

GeographicCRS = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'GeographicCRS'), GeographicCRSType, documentation='', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/deprecatedTypes.xsd', 451, 1))
_Namespace_gml.addCategoryObject('elementBinding', GeographicCRS.name().localName(), GeographicCRS)

GeocentricCRS = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'GeocentricCRS'), GeocentricCRSType, documentation='', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/deprecatedTypes.xsd', 483, 1))
_Namespace_gml.addCategoryObject('elementBinding', GeocentricCRS.name().localName(), GeocentricCRS)

LinearRing = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'LinearRing'), LinearRingType, documentation='A LinearRing is defined by four or more coordinate tuples, with linear interpolation between them; the first and last coordinates shall be coincident. The number of direct positions in the list shall be at least four.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/geometryBasic2d.xsd', 115, 1))
_Namespace_gml.addCategoryObject('elementBinding', LinearRing.name().localName(), LinearRing)

Ring = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'Ring'), RingType, documentation='A ring is used to represent a single connected component of a surface boundary as specified in ISO 19107:2003, 6.3.6.\nEvery gml:curveMember references or contains one curve, i.e. any element which is substitutable for gml:AbstractCurve. In the context of a ring, the curves describe the boundary of the surface. The sequence of curves shall be contiguous and connected in a cycle.\nIf provided, the aggregationType attribute shall have the value "sequence".', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/geometryPrimitives.xsd', 632, 1))
_Namespace_gml.addCategoryObject('elementBinding', Ring.name().localName(), Ring)

Tin = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'Tin'), TinType, documentation='A tin is a triangulated surface that uses the Delauny algorithm or a similar algorithm complemented with consideration of stoplines (stopLines), breaklines (breakLines), and maximum length of triangle sides (maxLength). controlPoint shall contain a set of the positions (three or more) used as posts for this TIN (corners of the triangles in the TIN). See ISO 19107:2003, 6.4.39 for details.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/geometryPrimitives.xsd', 754, 1))
_Namespace_gml.addCategoryObject('elementBinding', Tin.name().localName(), Tin)

Conversion = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'Conversion'), ConversionType, documentation='gml:Conversion is a concrete operation on coordinates that does not include any change of Datum. The best-known example of a coordinate conversion is a map projection. The parameters describing coordinate conversions are defined rather than empirically derived. Note that some conversions have no parameters.\nThis concrete complex type can be used without using a GML Application Schema that defines operation-method-specialized element names and contents, especially for methods with only one Conversion instance.\nThe usesValue property elements are an unordered list of composition associations to the set of parameter values used by this conversion operation.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/coordinateOperations.xsd', 221, 1))
_Namespace_gml.addCategoryObject('elementBinding', Conversion.name().localName(), Conversion)

Transformation = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'Transformation'), TransformationType, documentation='gml:Transformation is a concrete object element derived from gml:GeneralTransformation (13.6.2.13).\nThis concrete object can be used for all operation methods, without using a GML Application Schema that defines operation-method-specialized element names and contents, especially for methods with only one Transformation instance.\nThe parameterValue elements are an unordered list of composition associations to the set of parameter values used by this conversion operation.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/coordinateOperations.xsd', 257, 1))
_Namespace_gml.addCategoryObject('elementBinding', Transformation.name().localName(), Transformation)

ProjectedCRS = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'ProjectedCRS'), ProjectedCRSType, documentation='gml:ProjectedCRS is a 2D coordinate reference system used to approximate the shape of the earth on a planar surface, but in such a way that the distortion that is inherent to the approximation is carefully controlled and known. Distortion correction is commonly applied to calculated bearings and distances to produce values that are a close match to actual field values.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/coordinateReferenceSystems.xsd', 162, 1))
_Namespace_gml.addCategoryObject('elementBinding', ProjectedCRS.name().localName(), ProjectedCRS)

DerivedCRS = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'DerivedCRS'), DerivedCRSType, documentation='gml:DerivedCRS is a single coordinate reference system that is defined by its coordinate conversion from another single coordinate reference system known as the base CRS. The base CRS can be a projected coordinate reference system, if this DerivedCRS is used for a georectified grid coverage as described in ISO 19123, Clause 8.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/coordinateReferenceSystems.xsd', 194, 1))
_Namespace_gml.addCategoryObject('elementBinding', DerivedCRS.name().localName(), DerivedCRS)

TemporalDatum = pyxb.binding.basis.element(pyxb.namespace.ExpandedName(_Namespace_gml, 'TemporalDatum'), TemporalDatumType, documentation='A gml:TemporalDatum defines the origin of a Temporal Reference System. This type omits the "anchorDefinition" and "realizationEpoch" elements and adds the "origin" element with the dateTime type.', location=pyxb.utils.utility.Location('http://schemas.opengis.net/gml/3.2.1/datums.xsd', 239, 1))
_Namespace_gml.addCategoryObject('elementBinding', TemporalDatum.name().localName(), TemporalDatum)



